const state={route:'dashboard',projects:[],current:null,step:1,selectedModule:null,previewSlide:0,studentModule:null,studentSlide:0,studentModulesCollapsed:false,studentStepStartedAt:0,activeStudentStepKey:null,viewedSteps:{},assessmentIndex:0,answers:{},inlineAnswers:{},completedModules:[],assessmentAttempts:0,assessmentPassed:false,lastScore:null,studentProfile:null,pendingCourseId:null,profileReturnRoute:null,certificateInfo:null};
const STUDENT_CONTENT_STEP_MS=5000;
let studentAdvanceTimer=null;
const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plainNorm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const STUDENT_PROFILE_KEY='fortix_student_profile_v1';
function loadStudentProfile(){try{return JSON.parse(localStorage.getItem(STUDENT_PROFILE_KEY)||'null')}catch{return null}}
function saveStudentProfileData(profile){state.studentProfile=profile;try{localStorage.setItem(STUDENT_PROFILE_KEY,JSON.stringify(profile))}catch{}}
function studentIdentityKey(){const p=state.studentProfile||loadStudentProfile()||{};return plainNorm(p.document||p.email||p.name||'aluno').slice(0,64)||'aluno'}
function isIntroModule(m){const n=plainNorm(m?.learningTitle||m?.title||'');return ['introducao','apresentacao','boas vindas','roteiro','visao geral'].some(k=>n.includes(k))}
function toast(msg){const el=document.createElement('div');el.className='toast';el.textContent=msg;$('#toast').appendChild(el);setTimeout(()=>el.remove(),3300)}
async function api(url,opt={}){const r=await fetch(url,opt);if(!r.ok){let d;try{d=await r.json()}catch{d={detail:await r.text()}};throw new Error(typeof d.detail==='string'?d.detail:(d.detail?.message||JSON.stringify(d.detail)))}return r.json()}
const VERCEL_SAFE_UPLOAD_BYTES=4300000;
async function loadPdfJs(){if(window.pdfjsLib)return window.pdfjsLib;return await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';s.onload=()=>{if(!window.pdfjsLib)return reject(new Error('PDF.js nao carregou.'));window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';resolve(window.pdfjsLib)};s.onerror=()=>reject(new Error('Nao foi possivel carregar o leitor de PDF no navegador.'));document.head.appendChild(s)})}
async function extractPdfTextInBrowser(file){const pdfjs=await loadPdfJs(),data=new Uint8Array(await file.arrayBuffer()),pdf=await pdfjs.getDocument({data}).promise,pages=[],maxPages=Math.min(pdf.numPages||0,80);let payloadChars=0;for(let i=1;i<=maxPages;i++){const page=await pdf.getPage(i),content=await page.getTextContent(),text=content.items.map(x=>x.str||'').join(' ').replace(/\s+/g,' ').trim();if(text.length>=30){const clipped=text.slice(0,6000);pages.push({pageNumber:i,text:clipped});payloadChars+=clipped.length}if(payloadChars>2800000)break}if(!pages.length)throw new Error('O PDF nao possui texto selecionavel suficiente. Se ele for escaneado/imagem, precisa de OCR antes.');return {pages,totalPages:pdf.numPages||pages.length}}
const pdfRenderCache=new Map();
async function getPdfDocument(url){if(!url)throw new Error('PDF original sem URL publica. Configure o storage para preservar o arquivo.');if(pdfRenderCache.has(url))return pdfRenderCache.get(url);const pdfjs=await loadPdfJs();const task=pdfjs.getDocument({url,withCredentials:false}).promise;pdfRenderCache.set(url,task);return task}
function isGeneratedPlaceholder(url){return /^data:image\/svg/i.test(String(url||''))}
function pagePdfUrl(p){return p?.pdfUrl||state.current?.payload?.source?.url||''}
function attachLocalPdfPreview(project, url){
  const payload=project?.payload;
  if(!payload||!url)return;
  payload.source={...(payload.source||{}),url:payload.source?.url||url,localPreview:true};
  const total=Number(payload.source.pages||payload.sourcePages?.length||0)||1;
  if(!Array.isArray(payload.sourcePages)||!payload.sourcePages.length){
    payload.sourcePages=Array.from({length:total},(_,i)=>({page:i+1,title:`Pagina ${i+1}`,role:i===0?'COVER':'CONTENT',text:'',imageUrl:'',pdfUrl:url,hotspots:[],learning:{topics:[`Pagina ${i+1}`],keyPoints:[],explanations:[]}}));
  }
  payload.sourcePages=payload.sourcePages.map(p=>({...p,pdfUrl:p.pdfUrl||url,imageUrl:isGeneratedPlaceholder(p.imageUrl)?'':(p.imageUrl||'')}));
}
function pdfCanvasHtml(p){const url=pagePdfUrl(p);if(!url)return `<div class="pdf-render-missing"><b>PDF original não disponível</b><span>Configure o storage para exibir a página real no preview.</span></div>`;return `<div class="pdf-render-box" data-pdf-url="${esc(url)}" data-page="${Number(p.page)||1}"><div class="spinner"></div><span>Renderizando página ${Number(p.page)||1} do PDF original...</span></div>`}
async function hydratePdfCanvases(){const boxes=$$('.pdf-render-box:not([data-rendered])');for(const box of boxes){box.dataset.rendered='1';try{const url=box.dataset.pdfUrl,pageNumber=Number(box.dataset.page)||1,pdf=await getPdfDocument(url),page=await pdf.getPage(Math.min(pageNumber,pdf.numPages||pageNumber)),viewport=page.getViewport({scale:1}),maxWidth=Math.max(320,Math.min(980,box.clientWidth||760)),scale=Math.min(1.7,maxWidth/viewport.width),scaled=page.getViewport({scale}),canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');canvas.width=Math.floor(scaled.width);canvas.height=Math.floor(scaled.height);await page.render({canvasContext:ctx,viewport:scaled}).promise;box.innerHTML='';box.appendChild(canvas);box.classList.add('ready')}catch(e){box.classList.add('failed');box.innerHTML=`<b>Não foi possível renderizar esta página.</b><span>${esc(e.message||'Erro ao abrir PDF.')}</span>`}}}
function fmtBytes(n){if(n<1024)return n+' B';if(n<1048576)return (n/1024).toFixed(1)+' KB';return (n/1048576).toFixed(1)+' MB'}
function statusBadge(s){return s==='PUBLISHED'?'<span class="badge published">Publicado</span>':'<span class="badge review">Em revisão</span>'}
function setHeader(t,s){$('#pageTitle').textContent=t;$('#pageSubtitle').textContent=s}
function setRoute(route){state.route=route;$$('.nav').forEach(n=>n.classList.toggle('active',n.dataset.route===route));render()}
function steps(active){const names=['Upload','Análise','Estrutura','Preview','Revisão','Publicação'];return `<div class="steps">${names.map((n,i)=>`<div class="step ${i+1===active?'active':i+1<active?'done':''}"><span class="num">${i+1<active?'✓':i+1}</span><span>${n}</span></div>`).join('')}</div>`}
async function loadProjects(){state.projects=await api('/api/projects')}
function stats(){const published=state.projects.filter(p=>p.status==='PUBLISHED').length;const review=state.projects.length-published;const modules=state.projects.reduce((a,p)=>a+p.modules,0),q=state.projects.reduce((a,p)=>a+p.questions,0);return {published,review,modules,q}}
function dashboard(){setHeader('Central de treinamentos','Transforme PDFs em treinamentos interativos, revise e publique.');const s=stats();return `<div class="content"><section class="hero"><div><h2>Do PDF ao treinamento interativo em um fluxo controlado.</h2><p>O documento é extraído, estruturado em módulos, convertido em conteúdo didático, recebe avaliação e só então fica pronto para publicação.</p><button class="btn primary" onclick="newTraining()">＋ Criar treinamento</button></div><div style="min-width:220px;align-self:center"><div class="notice" style="background:rgba(255,255,255,.08);color:#dce6f0"><b>Modo local</b><br><span style="font-size:12px">PDF processado no seu servidor. A opção de apagar o original após a extração vem ativada.</span></div></div></section><div class="grid cols4 mt"><div class="stat"><span class="label">TREINAMENTOS</span><strong>${state.projects.length}</strong></div><div class="stat"><span class="label">PUBLICADOS</span><strong>${s.published}</strong></div><div class="stat"><span class="label">MÓDULOS GERADOS</span><strong>${s.modules}</strong></div><div class="stat"><span class="label">QUESTÕES</span><strong>${s.q}</strong></div></div>${projectsTable('Treinamentos recentes')}</div>`}
function projectsTable(title='Biblioteca'){return `<div class="section-title"><div><h3>${title}</h3><p>Projetos salvos neste ambiente local.</p></div></div><div class="card">${state.projects.length?state.projects.map(p=>`<div class="project-row"><div><div class="project-title">${esc(p.title)}</div><div class="project-meta">${esc(p.filename)}</div></div><div>${statusBadge(p.status)}</div><div><b>${p.modules}</b><small class="muted"> módulos</small></div><div><b>${p.questions}</b><small class="muted"> questões</small></div><div style="display:flex;gap:7px"><button class="btn outline" onclick="openProject('${p.id}',3)">Abrir</button><button class="btn danger" onclick="deleteProject('${p.id}')">Excluir</button></div></div>`).join(''):'<div class="empty">Nenhum treinamento criado ainda.</div>'}</div>`}
function library(){setHeader('Treinamentos','Gerencie rascunhos e treinamentos publicados.');return `<div class="content">${projectsTable()}</div>`}
function newTraining(){state.current=null;state.step=1;setRoute('new')}
function uploadView(){setHeader('Novo treinamento','Envie o PDF que será transformado em treinamento.');return `<div class="content">${steps(1)}<div class="upload-wrap"><div class="card"><div class="card-head"><div><b>1. Material de origem</b><div class="project-meta">PDF com até 80 MB</div></div></div><div class="card-body"><div id="dropzone" class="dropzone"><div class="drop-icon">⇧</div><h3>Arraste e solte seu PDF aqui</h3><p>ou selecione o arquivo no computador</p><input id="fileInput" type="file" accept="application/pdf,.pdf" hidden><button class="btn primary" onclick="$('#fileInput').click()">Selecionar PDF</button><div id="fileInfo" class="file-info"></div></div><div class="mt"><label class="check"><input type="checkbox" id="deleteSource" checked><span><b>Apagar o PDF original após a extração</b><br><span class="muted">As imagens fiéis de todas as páginas permanecem no treinamento. Desmarque apenas se também quiser manter o arquivo PDF original para download.</span></span></label></div><div class="toolbar"><span></span><button id="uploadBtn" class="btn primary" disabled onclick="uploadPdf()">Analisar documento →</button></div></div></div><div class="card"><div class="card-head"><b>Como o sistema trabalha</b></div><div class="card-body"><div class="check">✓ <span>Extrai o texto selecionável do PDF e cria aulas interativas.</span></div><div class="check">✓ <span>Organiza o conteúdo em módulos, aulas, checklists e perguntas.</span></div><div class="check">✓ <span>Mantém o material como origem técnica, mas o aluno navega pelo treinamento interativo.</span></div><div class="check">✓ <span>Gera quiz proporcional ao conteúdo: módulos de 1 página não recebem quiz; módulos maiores recebem poucas perguntas conforme a densidade.</span></div><div class="check">✓ <span>Mostra o conteúdo rastreado para revisão antes da publicação.</span></div><div class="notice info mt"><b>V1.6.0 — Materiais e certificado</b><br>No modo aluno, páginas de conteúdo liberam o avanço após 5 segundos. Introdução, objetivo, roteiro/apresentação e quizzes não exigem espera. As perguntas dos módulos continuam opcionais e não bloqueiam o aluno.</div></div></div></div></div>`}
function bindUpload(){const fi=$('#fileInput'),dz=$('#dropzone');if(!fi)return;fi.onchange=()=>showFile(fi.files[0]);dz.ondragover=e=>{e.preventDefault();dz.classList.add('drag')};dz.ondragleave=()=>dz.classList.remove('drag');dz.ondrop=e=>{e.preventDefault();dz.classList.remove('drag');if(e.dataTransfer.files[0]){fi.files=e.dataTransfer.files;showFile(e.dataTransfer.files[0])}}}
function showFile(f){if(!f)return;const box=$('#fileInfo');box.classList.add('show');box.innerHTML=`<div><b>📄 ${esc(f.name)}</b><div class="project-meta">${fmtBytes(f.size)}</div></div><span class="badge published">Pronto</span>`;$('#uploadBtn').disabled=false}
async function uploadPdf(){const f=$('#fileInput').files[0];if(!f)return;const btn=$('#uploadBtn');btn.disabled=true;btn.innerHTML='<span class="spinner"></span> Extraindo e analisando...';const localPdfUrl=URL.createObjectURL(f);try{if(f.size>VERCEL_SAFE_UPLOAD_BYTES){btn.innerHTML='<span class="spinner"></span> Lendo texto do PDF no navegador...';const extracted=await extractPdfTextInBrowser(f);btn.innerHTML='<span class="spinner"></span> Gerando treinamento pelo conteúdo...';state.current=await api('/api/projects/upload-text',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:f.name,size:f.size,totalPages:extracted.totalPages,pages:extracted.pages})})}else{const fd=new FormData();fd.append('file',f);fd.append('delete_source_after_extract',$('#deleteSource').checked?'true':'false');state.current=await api('/api/projects/upload',{method:'POST',body:fd})}attachLocalPdfPreview(state.current,localPdfUrl);state.step=2;await loadProjects();render()}catch(e){try{URL.revokeObjectURL(localPdfUrl)}catch{}toast('Erro: '+e.message);btn.disabled=false;btn.textContent='Analisar documento →'}}
function analysisView(){const p=state.current.payload,a=p.analysis,s=p.source;const strategy=a.structureStrategy==='agenda_guided'?'Roteiro/sumário guiou a estrutura':a.structureStrategy==='hierarchical_headings'?'Hierarquia inferida por títulos fortes e subtítulos':'Estrutura inferida por títulos e assunto';setHeader('Análise do documento','O motor reconstruiu o documento antes de criar módulos e tópicos.');return `<div class="content">${steps(2)}<div class="notice ${a.warnings.length?'warn':'good'}"><b>${a.warnings.length?'Análise concluída com pontos para revisar':'Análise estrutural concluída'}</b><br>${a.warnings.length?a.warnings.map(esc).join('<br>'):'O motor encontrou uma estrutura consistente e rastreável.'}</div><div class="grid cols4 mt"><div class="stat"><span class="label">PÁGINAS</span><strong>${s.pages}</strong></div><div class="stat"><span class="label">PÁGINAS COM TEXTO</span><strong>${s.searchablePages}</strong></div><div class="stat"><span class="label">PÁGINAS VISUAIS</span><strong>${a.visualPages||0}</strong></div><div class="stat"><span class="label">VISUAIS EXTRAÍDOS</span><strong>${s.visualAssets||0}</strong></div></div><div class="analysis-layout mt"><div class="card"><div class="card-head"><b>Estrutura reconhecida</b></div><div class="card-body"><div class="check">✓ <span><b>${a.modules}</b> módulos</span></div><div class="check">✓ <span><b>${a.topics}</b> tópicos</span></div><div class="check">✓ <span><b>${a.criticalConcepts}</b> conteúdos críticos</span></div><div class="check">✓ <span><b>${a.questions}</b> questões iniciais</span></div><div class="check">↔ <span><b>${a.continuityMerges||0}</b> continuidades de linhas/parágrafos recompostas</span></div><div class="check">▤ <span><b>${a.coveragePercent??'—'}%</b> do texto útil associado ao curso</span></div><div class="notice info mt"><b>${esc(strategy)}</b><br>${a.agendaDetected?`Roteiro detectado na página ${a.agendaPage}, com ${a.agendaItems.length} assuntos.`:`Nenhum roteiro confiável foi encontrado; os módulos foram inferidos sem usar um curso pré-programado.${a.moduleOrdering?.changed?' A ordem de exibição foi normalizada pedagogicamente sem perder as páginas de origem.':''}`}</div></div></div><div class="card"><div class="card-head"><b>${a.agendaDetected?'Roteiro encontrado':'Leitura estrutural'}</b></div><div class="card-body">${a.agendaDetected?`<div class="detected-outline">${a.agendaItems.map((x,i)=>`<div><span>${i+1}</span><b>${esc(x)}</b></div>`).join('')}</div>`:['Validação do PDF','Remoção de cabeçalho/rodapé recorrente','Reconstrução de linhas e continuidade','Detecção de títulos reais','Separação de páginas visuais','Agrupamento semântico de módulos','Classificação didática e avaliação'].map(x=>`<div class="check">✓ <span>${x}</span></div>`).join('')}</div></div><div class="card"><div class="card-head"><b>Arquivo</b></div><div class="card-body"><b>${esc(s.filename)}</b><div class="project-meta">${fmtBytes(s.size)}</div><div class="mt"><span class="badge type">Extração ${esc(s.searchability)}</span></div><div class="mt">${state.current.sourceDeleted?'<span class="badge review">PDF original removido</span>':'<span class="badge published">PDF original preservado</span>'}</div><p class="muted mt">As imagens úteis extraídas permanecem vinculadas aos tópicos mesmo quando o PDF original é removido.</p></div></div></div><div class="toolbar"><button class="btn outline" onclick="newTraining()">← Novo upload</button><button class="btn primary" onclick="goStep(3)">Ver estrutura encontrada →</button></div></div>`}
function structureTopicEvidence(t,i){const kp=(t.keyPoints||[]).slice(0,3);const blocks=t.contentBlocks||{};const excerpt=(t.sourcePreview||t.content||'').trim();return `<div class="structure-topic"><div class="structure-topic-head"><div><span class="topic-number">${i+1}</span><div><b>${esc(t.title)}</b><small>Páginas ${range(t.sourcePages)} · ${t.wordCount||0} palavras · confiança ${Math.round((t.confidence||0)*100)}%</small></div></div>${sourceButton(t)}</div>${t.summary?`<p class="structure-topic-summary">${esc(t.summary)}</p>`:''}${kp.length?`<div class="structure-keypoints">${kp.map(x=>`<div>✓ <span>${esc(x)}</span></div>`).join('')}</div>`:''}${excerpt?`<details class="source-preview"><summary>Ver conteúdo rastreado</summary><div>${esc(excerpt.slice(0,1200))}${excerpt.length>1200?'…':''}</div></details>`:''}<div class="structure-topic-meta"><span class="tag ${t.contentType}">${typeTitle(t.contentType)}</span><span class="tag GENERAL_CONTENT">${blocks.paragraphs||0} parágrafo(s)</span><span class="tag GENERAL_CONTENT">${blocks.listItems||0} item(ns) de lista</span>${(t.visuals||[]).length?`<span class="tag GENERAL_CONTENT">${(t.visuals||[]).length} visual(is)</span>`:''}</div></div>`}
function structureView(){const p=state.current.payload;setHeader('Estrutura e conteúdo reconhecido','Confira a hierarquia e, principalmente, o que o motor realmente rastreou do PDF.');const mod=selected();const anchorLabel=k=>({agenda_first:'Início após roteiro',agenda_match:'Título/assunto reconhecido',inferred_between_anchors:'Inferido entre assuntos do roteiro',theme_shifted:'Início ampliado pelo contexto',repaired_sequence:'Sequência reconstruída',semantic_heading:'Título semântico',hierarchical_heading:'Título principal da hierarquia'}[k]||'Estrutura reconhecida');return `<div class="content">${steps(3)}<div class="analysis-layout structure-layout"><div class="card"><div class="card-head"><b>Módulos (${p.modules.length})</b></div><div class="card-body module-list">${p.modules.map((m,i)=>`<button class="module-item ${mod?.id===m.id?'active':''}" onclick="selectModule('${m.id}')" style="text-align:left"><b>${i+1}. ${esc(m.title)}</b><small>${m.topics.length} tópicos · págs. ${modulePages(m)} · ${m.sourceWordCount||0} palavras</small></button>`).join('')}</div></div><div class="card"><div class="card-head"><div><b>${esc(mod?.title||'')}</b><div class="project-meta">${mod?esc(anchorLabel(mod.anchorKind)):''}</div></div><span class="badge type">Estrutura ${Math.round((mod?.structureConfidence||mod?.confidence||0)*100)}%</span></div><div class="card-body">${mod?`<div class="module-source-intro"><div class="micro-title">O QUE ESTE MÓDULO CONTÉM</div><p>${esc(mod.description)}</p></div><div class="continuity-strip four"><div><span>Páginas</span><b>${modulePages(mod)}</b></div><div><span>Texto rastreado</span><b>${mod.sourceWordCount||0} palavras</b></div><div><span>Tópicos</span><b>${mod.topics.length}</b></div><div><span>Visuais</span><b>${mod.sourceVisualCount||0}</b></div></div><h4>Objetivos gerados a partir do conteúdo</h4><ul class="objective-list">${mod.learningObjectives.map(o=>`<li>${esc(o)}</li>`).join('')}</ul>${(mod.keyPoints||[]).length?`<h4>Pontos centrais encontrados</h4><div class="source-list">${mod.keyPoints.slice(0,5).map(x=>`<div><span>✓</span><p>${esc(x)}</p></div>`).join('')}</div>`:''}<div class="section-separator"><h4>Conteúdo rastreado por tópico</h4><small>Não é só o nome do tópico: abaixo está a evidência que será transformada na aula.</small></div><div class="structure-topics">${mod.topics.map((t,i)=>structureTopicEvidence(t,i)).join('')}</div>`:''}</div></div><div class="card"><div class="card-head"><b>Leitura do motor</b></div><div class="card-body"><div class="check">◈ <span>${p.analysis.topics} tópicos</span></div><div class="check">⚠ <span>${p.analysis.criticalConcepts} conteúdos críticos</span></div><div class="check">▧ <span>${p.source.visualAssets||0} recursos visuais extraídos</span></div><div class="check">? <span>${p.analysis.interactiveQuestions||0} interações no conteúdo</span></div><div class="check">✓ <span>${p.questions.length} questões finais</span></div><div class="check">▤ <span><b>${p.analysis.coveragePercent??'—'}%</b> de cobertura textual</span></div><div class="notice info mt"><b>Regra V1.0</b><br>O motor pode organizar módulos e tópicos, mas não reescreve a página do PDF. No player, as páginas originais são exibidas integralmente e a interatividade fica em uma camada separada.</div><div class="notice warn mt"><b>O que revisar</b><br>Se um módulo tiver poucas palavras ou um título que pareça continuação de frase, a divisão ainda merece revisão humana.</div></div></div></div><div class="toolbar"><button class="btn outline" onclick="goStep(2)">← Voltar</button><button class="btn primary" onclick="goStep(4)">Ver treinamento completo →</button></div></div>`}
function selected(){const mods=state.current?.payload.modules||[];if(!state.selectedModule||!mods.some(m=>m.id===state.selectedModule))state.selectedModule=mods[0]?.id;return mods.find(m=>m.id===state.selectedModule)}
function selectModule(id){state.selectedModule=id;state.previewSlide=0;render()}
function range(arr){
  const a=[...new Set((arr||[]).map(Number).filter(n=>Number.isFinite(n)&&n>0))].sort((x,y)=>x-y);
  if(!a.length)return '—';
  const groups=[];let start=a[0],prev=a[0];
  for(let i=1;i<a.length;i++){
    const n=a[i];
    if(n===prev+1){prev=n;continue}
    groups.push(start===prev?String(start):`${start}-${prev}`);
    start=prev=n;
  }
  groups.push(start===prev?String(start):`${start}-${prev}`);
  return groups.length<=4?groups.join(', '):`${groups.slice(0,4).join(', ')} +${groups.length-4}`;
}
function modulePages(m){return range((m?.displayPages?.length?m.displayPages:m?.sourcePages)||[])}
function typeTitle(t){return {RISK:'Atenção ao risco',PROHIBITION:'Proibição',PROCEDURE:'Procedimento',OBLIGATION:'Obrigação',EPI:'EPI',EPC:'EPC',EMERGENCY:'Emergência',DEFINITION:'Conceito',LEGAL_REFERENCE:'Referência normativa',RESPONSIBILITY:'Responsabilidade',BENEFIT:'Benefício',CONSEQUENCE:'Consequência',PRACTICE:'Prática',GENERAL_CONTENT:'Conteúdo'}[t]||t}
function sourceButton(t){return `<button class="btn outline" style="padding:6px 9px;font-size:11px" onclick='showSource(${JSON.stringify(t.sourcePages)})'>Ver fonte</button>`}
function topicParagraphs(t){const ps=(t.paragraphs||[]).filter(Boolean);if(ps.length)return ps;return String(t.content||'').split(/\n\n+/).filter(x=>x.trim()).slice(0,5)}
function topicKeyPoints(t){return (t.keyPoints||[]).filter(Boolean).slice(0,5)}
function typeIcon(t){return {RISK:'⚠',PROHIBITION:'⛔',PROCEDURE:'☑',OBLIGATION:'!',EPI:'⛑',EPC:'🛡',EMERGENCY:'✚',DEFINITION:'◇',LEGAL_REFERENCE:'§',RESPONSIBILITY:'◎',BENEFIT:'★',CONSEQUENCE:'↘',PRACTICE:'↗',GENERAL_CONTENT:'●'}[t]||'●'}
function renderCallout(t){const c=t.callout;if(!c?.text)return '';return `<div class="learning-callout ${t.contentType}"><div class="callout-icon">${typeIcon(t.contentType)}</div><div><b>${esc(c.title||typeTitle(t.contentType))}</b><p>${esc(c.text)}</p></div></div>`}
function renderKeyPoints(t){const pts=topicKeyPoints(t);if(!pts.length)return '';return `<div class="keypoint-box"><div class="micro-title">O QUE VOCÊ PRECISA GUARDAR</div><div class="keypoint-grid">${pts.map((x,i)=>`<div class="keypoint"><span>${i+1}</span><p>${esc(x)}</p></div>`).join('')}</div></div>`}
function renderSteps(t){const st=(t.steps||[]).filter(Boolean);if(!st.length)return '';return `<div class="steps-content"><div class="micro-title">PASSO A PASSO</div>${st.map((x,i)=>`<div class="procedure-step"><span>${i+1}</span><div>${esc(x)}</div></div>`).join('')}</div>`}
function renderActivity(t){if(!t.activity?.prompt)return '';return `<div class="practice-card"><div class="practice-icon">↗</div><div><b>${esc(t.activity.title||'Conecte com a prática')}</b><p>${esc(t.activity.prompt)}</p></div></div>`}
function renderCheckpoint(t,interactive=true){const q=t.checkpoint;if(!q)return '';const name='cp_'+t.id;return `<div class="checkpoint"><div class="checkpoint-head"><div><span>CHECKPOINT</span><b>Confira se ficou claro</b></div><span class="checkpoint-badge">1 pergunta</span></div><p class="checkpoint-question">${esc(q.question)}</p>${q.statement?`<div class="statement">“${esc(q.statement)}”</div>`:''}<div class="checkpoint-options">${q.options.map((o,i)=>`<label><input type="radio" name="${name}" value="${i}"><span>${esc(o)}</span></label>`).join('')}</div>${interactive?`<button class="btn soft" onclick="checkTopic('${t.id}')">Verificar resposta</button><div id="cp_result_${t.id}" class="checkpoint-result"></div>`:''}</div>`}
function checkTopic(id){const p=state.current.payload;let t=null;for(const m of p.modules){t=m.topics.find(x=>x.id===id);if(t)break}if(!t?.checkpoint)return;const chosen=document.querySelector(`input[name="cp_${id}"]:checked`),out=$(`#cp_result_${id}`);if(!chosen){out.className='checkpoint-result warn';out.textContent='Selecione uma resposta.';return}const ok=Number(chosen.value)===t.checkpoint.correctIndex;out.className='checkpoint-result '+(ok?'good':'bad');out.innerHTML=`<b>${ok?'Correto!':'Ainda não.'}</b> ${esc(t.checkpoint.explanation||'Revise o conteúdo acima.')}`}
function renderLists(t){const ls=(t.lists||[]).filter(x=>x?.length);if(!ls.length)return '';return ls.map(items=>`<div class="source-list">${items.map(x=>`<div><span>✓</span><p>${esc(x)}</p></div>`).join('')}</div>`).join('')}
function renderVisuals(t){const vs=(t.visuals||[]).filter(x=>x?.url);if(!vs.length)return '';return `<div class="source-visuals"><div class="micro-title">RECURSOS VISUAIS DO MATERIAL</div><div class="visual-grid">${vs.slice(0,8).map(v=>`<figure><img src="${esc(v.url)}" loading="lazy" alt="Recurso visual da página ${v.page}"><figcaption>Página ${v.page}</figcaption></figure>`).join('')}</div></div>`}
function renderGlossary(t){const gs=(t.pedagogy?.glossary||[]).filter(x=>x?.term&&x?.definition);if(!gs.length)return '';return `<div class="ped-glossary"><div class="micro-title">TERMOS DO MATERIAL</div>${gs.map(g=>`<div class="glossary-row"><b>${esc(g.term)}</b><p>${esc(g.definition)}</p></div>`).join('')}</div>`}
function renderLegalRefs(t){const rs=(t.pedagogy?.legalReferences||[]).filter(Boolean);if(!rs.length)return '';return `<div class="legal-ref-strip"><span>§</span><div><b>Referências identificadas</b><div>${rs.map(x=>`<em>${esc(x)}</em>`).join('')}</div></div></div>`}
function renderPedagogicalIntro(t){const p=t.pedagogy||{};const simple=p.simpleExplanation||t.summary||'';if(!p.opening&&!simple)return '';return `<div class="pedagogy-stack">${p.opening?`<div class="ped-opening"><span>01</span><div><b>Antes de entrar no texto</b><p>${esc(p.opening)}</p></div></div>`:''}${simple?`<div class="ped-simple"><div class="micro-title">EM LINGUAGEM DIRETA</div><p>${esc(simple)}</p></div>`:''}</div>`}
function renderPedagogicalFocus(t){const p=t.pedagogy||{};const pts=(p.remember||t.keyPoints||[]).filter(Boolean).slice(0,6);if(!pts.length)return '';return `<div class="ped-focus"><div class="ped-focus-head"><span>02</span><div><b>${esc(p.focusTitle||'O que você precisa guardar')}</b><small>Conteúdo selecionado a partir da fonte</small></div></div><div class="ped-focus-grid">${pts.map((x,i)=>`<div><span>${i+1}</span><p>${esc(x)}</p></div>`).join('')}</div></div>`}
function renderPractical(t){const p=t.pedagogy||{};if(!p.practicalApplication)return renderActivity(t);return `<div class="ped-practice"><div class="practice-icon">↗</div><div><span>03 · APLICAÇÃO</span><b>Leve o conteúdo para a atividade</b><p>${esc(p.practicalApplication)}</p></div></div>`}
function uiNorm(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function introLikeModule(m){const n=uiNorm(m?.learningTitle||m?.title);return /(^| )(introducao|apresentacao|boas vindas|boas vindas|roteiro|visao geral)( |$)/.test(n)}
function topicAnchors(t){const p=t.pedagogy||{};return (p.remember||t.keyPoints||[]).filter(Boolean)}
function topicDensity(t){const pts=topicAnchors(t),lists=(t.lists||[]).reduce((a,x)=>a+(x?.length||0),0),gl=(t.pedagogy?.glossary||[]).length,refs=(t.pedagogy?.legalReferences||[]).length;return {words:t.wordCount||0,points:pts.length,lists,glossary:gl,refs,score:(t.wordCount||0)+pts.length*30+lists*18+gl*35+refs*12}}
function renderLearningGoal(t){const g=t.pedagogy?.learningGoal;if(!g)return '';return `<div class="learning-goal"><span>◎</span><div><b>Ao terminar esta etapa, você deverá</b><p>${esc(g)}</p></div></div>`}
function renderSourceDigest(t){const pts=topicAnchors(t).slice(0,3);if(!pts.length)return '';return `<div class="source-digest"><div class="micro-title">O MATERIAL APRESENTA</div>${pts.map(x=>`<div><span>✓</span><p>${esc(x)}</p></div>`).join('')}</div>`}
function practicalIsUseful(t){const d=topicDensity(t),type=t.contentType||'GENERAL_CONTENT',text=uiNorm(t.pedagogy?.practicalApplication||'');if(!text)return false;if(['RISK','PROHIBITION','OBLIGATION','RESPONSIBILITY','PROCEDURE','EPI','EPC','EMERGENCY','PRACTICE'].includes(type))return d.points+d.lists>=2||d.words>=110;if(type==='BENEFIT'||type==='CONSEQUENCE')return d.words>=120&&d.points>=2;if(type==='DEFINITION')return d.words>=170&&d.points>=2;if(type==='LEGAL_REFERENCE')return d.points+d.lists>=3&&d.words>=180;return false}
function questionIsUseful(m,t){if(!m||introLikeModule(m))return false;const d=topicDensity(t),tn=uiNorm(t.learningTitle||t.title),type=t.contentType||'GENERAL_CONTENT';if(/(^| )(introducao|apresentacao|roteiro|objetivo|visao geral)( |$)/.test(tn))return false;const minimum=['RISK','PROHIBITION','OBLIGATION','RESPONSIBILITY','PROCEDURE','EPI','EPC','EMERGENCY'].includes(type)?100:['BENEFIT','CONSEQUENCE','PRACTICE'].includes(type)?110:130;if(d.words<minimum)return false;if(d.points+d.lists+d.glossary<2)return false;return (t.interactions||[]).length>0}
function renderSourceAccordion(t){const raw=(t.content||'').trim();if(!raw)return '';return `<details class="lesson-source-accordion"><summary>Consultar redação original rastreada</summary><div class="source-origin-head"><span>SOURCE</span><small>Páginas ${range(t.sourcePages)} · ${t.wordCount||0} palavras</small></div><div class="source-original-text">${esc(raw)}</div></details>`}
function renderTopic(t,{source=true,checkpoint=true}={}){const display=t.learningTitle||t.pedagogy?.learningTitle||t.title;return `<section class="lesson-section pedagogical" id="topic_${t.id}"><div class="lesson-heading"><div class="lesson-icon ${t.contentType}">${typeIcon(t.contentType)}</div><div><span class="lesson-kicker">${typeTitle(t.contentType)}</span><h3>${esc(display)}</h3>${display!==t.title?`<small class="source-title-note">No PDF: ${esc(t.title)}</small>`:''}</div>${source?sourceButton(t):''}</div>${renderPedagogicalIntro(t)}${renderGlossary(t)}${renderLegalRefs(t)}${renderCallout(t)}${renderPedagogicalFocus(t)}${renderSteps(t)}${renderVisuals(t)}${renderPractical(t)}${checkpoint?renderCheckpoint(t,true):''}${source?renderSourceAccordion(t):''}${source?`<div class="source-line">Camada didática: ${esc(t.pedagogy?.origin||'ADAPTED_FROM_SOURCE')} · fonte: páginas ${range(t.sourcePages)} · confiança ${Math.round((t.confidence||0)*100)}%</div>`:''}</section>`}
function visualCardHtml(vs){return `<div class="deck-visuals">${vs.map(v=>`<figure><img src="${esc(v.url)}" loading="lazy" alt="Recurso visual da página ${v.page}"><figcaption>Material de origem · página ${v.page}</figcaption></figure>`).join('')}</div>`}
function interactionHtml(t,q,mode,idx){const qid=q.id||`legacy_${t.id}_${idx}`,name=`iq_${mode}_${qid}`;const saved=state.inlineAnswers[qid];return `<div class="interaction-card"><div class="interaction-top"><div><span class="interaction-kicker">${esc(q.label||'PERGUNTA INTERATIVA')}</span><h3>${esc(q.question)}</h3></div><span class="interaction-count">${idx+1}</span></div>${q.statement?`<div class="statement">“${esc(q.statement)}”</div>`:''}<div class="interactive-options">${(q.options||[]).map((o,i)=>`<label class="interactive-option ${saved?.selected===i?'selected':''}"><input type="radio" name="${name}" value="${i}" ${saved?.selected===i?'checked':''}><span><b>${String.fromCharCode(65+i)}</b>${esc(o)}</span></label>`).join('')}</div><button class="btn primary interaction-check" onclick="checkInlineInteraction('${t.id}','${qid}','${mode}')">Verificar resposta</button><div id="iq_result_${mode}_${qid}" class="checkpoint-result ${saved?(saved.correct?'good':'bad'):''}">${saved?`<b>${saved.correct?'Correto!':'Ainda não.'}</b> ${esc(q.explanation||'Revise o conteúdo deste tópico.')}`:''}</div><div class="source-line">Pergunta criada a partir das páginas ${range(q.sourcePages||t.sourcePages)} · ${esc(q.origin||'GENERATED_FROM_SOURCE')}</div></div>`}
function checkInlineInteraction(topicId,qid,mode){let topic=null,q=null;for(const m of state.current.payload.modules){topic=m.topics.find(t=>t.id===topicId);if(topic){q=(topic.interactions||[]).find(x=>x.id===qid)||topic.checkpoint;break}}if(!q)return;const chosen=document.querySelector(`input[name="iq_${mode}_${qid}"]:checked`),out=$(`#iq_result_${mode}_${qid}`);if(!chosen){out.className='checkpoint-result warn';out.textContent='Escolha uma alternativa antes de verificar.';return}const selected=Number(chosen.value),ok=selected===q.correctIndex;state.inlineAnswers[qid]={selected,correct:ok};out.className='checkpoint-result '+(ok?'good':'bad');out.innerHTML=`<b>${ok?'Correto!':'Ainda não.'}</b> ${esc(q.explanation||'Revise o conteúdo deste tópico.')}`;document.querySelectorAll(`input[name="iq_${mode}_${qid}"]`).forEach((x,i)=>x.closest('label')?.classList.toggle('selected',i===selected));if(mode==='student'){saveStudentProgress();render()}}
function interactionKey(t,q,idx){return q?.id||`legacy_${t.id}_${idx}`}
function lessonTrace(t,source){if(!source)return '';return `<div class="lesson-trace"><span>Fonte: páginas ${range(t.sourcePages)}</span><button class="btn outline" onclick='showSource(${JSON.stringify(t.sourcePages)})'>Ver conteúdo-fonte</button></div>`}
function topicDeck(t,{source=false,mode='preview',module=null}={}){
  const cards=[],p=t.pedagogy||{},display=t.learningTitle||p.learningTitle||t.title,d=topicDensity(t);
  const intro=renderPedagogicalIntro(t),goal=renderLearningGoal(t),digest=renderSourceDigest(t),gloss=renderGlossary(t),refs=renderLegalRefs(t),focus=renderCallout(t)+renderPedagogicalFocus(t),steps=renderSteps(t),trace=lessonTrace(t,source);
  // 1) Always start by teaching. References/glossary are support material, never a slide by themselves.
  let first=intro+goal;
  if(d.points<=4) first+=digest;
  if(d.glossary<=1) first+=gloss;
  if(d.refs<=2) first+=refs;
  if(first) cards.push({kind:'learn',label:'Entenda',title:display,html:`<div class="dense-lesson lesson-balanced">${first}${trace}</div>`,teachingWeight:1.25});

  // 2) A second teaching slide exists only when it adds substance. This is the main guard
  // against empty pages followed immediately by a quiz.
  let deepen='';
  if(focus&&(d.points>=2||d.lists>=2||d.words>=105)) deepen+=focus;
  if(d.points>4) deepen+=digest;
  if(d.glossary>=2) deepen+=gloss;
  if(d.refs>=3) deepen+=refs;
  if(steps) deepen+=steps;
  if(deepen) cards.push({kind:'focus',label:'Aprofunde',title:p.focusTitle||'Pontos essenciais',html:`<div class="dense-lesson lesson-balanced">${deepen}${trace}</div>`,teachingWeight:1.15});

  // 3) Visual/application slides are combined so a picture or a generic prompt never occupies
  // an almost empty screen on its own.
  const vs=(t.visuals||[]).filter(v=>v?.url),practical=practicalIsUseful(t)?renderPractical(t):'';
  if(vs.length||practical){
    // A lone source image supports the explanation instead of becoming a nearly empty slide.
    if(vs.length===1&&!practical&&cards.length){
      cards[cards.length-1].html=cards[cards.length-1].html.replace('</div>',`${visualCardHtml(vs)}</div>`);
      cards[cards.length-1].teachingWeight=(cards[cards.length-1].teachingWeight||0)+.35;
    }else{
      for(let i=0;i<Math.max(1,Math.ceil(vs.length/2));i++){
        const pair=vs.slice(i*2,i*2+2),visual=pair.length?visualCardHtml(pair):'';
        const app=(i===0?practical:'');
        if(visual||app) cards.push({kind:'practice',label:pair.length?'Veja e aplique':'Na prática',title:pair.length?'Observe e conecte ao trabalho':'Aplicação no trabalho',html:`<div class="dense-lesson lesson-balanced">${visual}${app}${trace}</div>`,teachingWeight:pair.length&&app?1.1:.75});
      }
    }
  }

  // Questions only appear after at least two real teaching moments and only if the backend
  // already approved a pertinent source-backed interaction for this topic.
  const taught=cards.reduce((a,c)=>a+(c.teachingWeight||0),0),teachingCards=cards.filter(c=>c.kind!=='interaction').length;
  if(questionIsUseful(module,t)&&taught>=2.15&&teachingCards>=2){
    (t.interactions||[]).slice(0,1).forEach((q,i)=>cards.push({kind:'interaction',label:'Cheque de entendimento',title:'Agora verifique o que aprendeu',interactionId:interactionKey(t,q,i),html:interactionHtml(t,q,mode,i)}));
  }
  return cards.length?cards:[{kind:'learn',label:'Conteúdo',title:display,html:`<div class="dense-lesson"><p class="lesson-copy">${esc(t.summary||t.content||'Conteúdo sem texto extraído.')}</p>${trace}</div>`,teachingWeight:1}]
}
function sourcePageByNumber(n){const p=(state.current?.payload?.sourcePages||[]).find(p=>Number(p.page)===Number(n));return p?{...p,pdfUrl:p.pdfUrl||state.current?.payload?.source?.url||''}:p}
function pageRoleLabel(role){return ({COVER:'Capa original',AGENDA:'Roteiro original',CLOSING:'Encerramento original',VISUAL_SUPPORT:'Página visual',CONTENT:'Página original'})[role]||'Página original'}
function pageHotspotOpen(page,index){const p=sourcePageByNumber(page),h=p?.hotspots?.[index];if(!h)return;modal(`<div class="source-hotspot-modal"><span class="badge type">${esc(h.kind==='HEADING'?'Título/destaque':h.kind==='CRITICAL'?'Ponto de atenção':'Trecho do material')}</span><h3>Página ${page}</h3><div class="source-text">${esc(h.text)}</div><p class="muted">Este destaque aponta para o texto da própria página original; o sistema não substituiu a redação do PDF.</p></div>`,'Destaque da página')}
function openNativePage(url,page){const student=state.route==='student-course'||state.route==='assessment';modal(`<div class="native-page-zoom"><img src="${esc(url)}" alt="Conteúdo ampliado"></div>`,student?'Conteúdo ampliado':`Página ${page} do PDF`)}
function pageLearningAside(p){const l=p?.learning||{},points=(l.keyPoints||[]).slice(0,4),topics=(l.topics||[]).slice(0,3),exps=(l.explanations||[]).slice(0,1),canZoom=!!p.imageUrl&&!isGeneratedPlaceholder(p.imageUrl);return `<aside class="native-page-aside"><div class="native-source-seal"><span>✓</span><div><b>Página original preservada</b><small>Nenhum texto desta página foi reescrito.</small></div></div>${topics.length?`<div class="native-aside-block"><span class="micro-title">ASSUNTOS RECONHECIDOS</span>${topics.map(x=>`<div class="native-topic-chip">${esc(x)}</div>`).join('')}</div>`:''}${points.length?`<div class="native-aside-block"><span class="micro-title">O QUE OBSERVAR</span>${points.map((x,i)=>`<div class="native-observe"><b>${i+1}</b><p>${esc(x)}</p></div>`).join('')}</div>`:''}${exps.length?`<details class="native-explain"><summary>Explicação de apoio</summary><p>${esc(exps[0])}</p><small>Camada de apoio adaptada; a página original ao lado continua sendo a fonte.</small></details>`:''}<div class="native-page-actions">${canZoom?`<button class="btn outline" onclick="openNativePage('${esc(p.imageUrl)}',${p.page})">⛶ Ampliar página</button>`:''}<button class="btn outline" onclick="showSource([${Number(p.page)}])">Texto extraído</button></div></aside>`}
function nativePageHtml(p){const hs=(p.hotspots||[]).slice(0,6),usePdf=pagePdfUrl(p)&&(!p.imageUrl||isGeneratedPlaceholder(p.imageUrl));return `<div class="pdf-native-layout"><div class="native-page-column"><div class="native-page-toolbar"><span><b>${pageRoleLabel(p.role)}</b> · página ${p.page} de ${state.current?.payload?.source?.pages||'?'}</span><small>${usePdf?'Página real renderizada do PDF original.':'Clique nos marcadores para explorar destaques do próprio PDF.'}</small></div><div class="native-page-canvas">${usePdf?pdfCanvasHtml(p):`<img src="${esc(p.imageUrl)}" loading="lazy" alt="Página original ${p.page} do PDF" onclick="openNativePage('${esc(p.imageUrl)}',${p.page})">`}${!usePdf?hs.map((h,i)=>`<button class="native-hotspot ${h.kind==='HEADING'?'heading':h.kind==='CRITICAL'?'critical':''}" style="left:${h.x}%;top:${h.y}%" onclick="event.stopPropagation();pageHotspotOpen(${p.page},${i})" title="Abrir destaque"><span>${i+1}</span></button>`).join(''):''}</div>${!usePdf&&hs.length?`<div class="native-hotspot-legend">${hs.map((h,i)=>`<button onclick="pageHotspotOpen(${p.page},${i})"><b>${i+1}</b>${esc(h.text.slice(0,80))}${h.text.length>80?'…':''}</button>`).join('')}</div>`:''}</div>${pageLearningAside(p)}</div>`}
function moduleQuizQuestions(m){return (state.current?.payload?.moduleQuizzes||[]).filter(q=>q.moduleId===m.id)}
function studentPageSupport(p){const l=p?.learning||{},exp=(l.explanations||[]).filter(Boolean)[0]||'',expCore=exp.replace(/^Nesta página, o material destaca:\s*/i,'').trim(),cmp=x=>String(x||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();const base=cmp(expCore),points=(l.keyPoints||[]).filter(Boolean).filter(x=>{const n=cmp(x);return !base||(!n.includes(base)&&!base.includes(n))}).slice(0,3);if(!points.length&&!expCore)return '';return `<div class="student-page-support ${points.length&&expCore?'':'single'}">${expCore?`<div class="student-support-explain"><span>💡</span><div><b>Entenda esta página</b><p>${esc(expCore)}</p></div></div>`:''}${points.length?`<div class="student-support-points"><b>Pontos importantes</b>${points.map(x=>`<div><span>✓</span><p>${esc(x)}</p></div>`).join('')}</div>`:''}</div>`}
function studentNativePageHtml(p){const support=studentPageSupport(p),usePdf=pagePdfUrl(p)&&(!p.imageUrl||isGeneratedPlaceholder(p.imageUrl));return `<div class="student-native-page student-focus-page"><div class="student-page-frame">${usePdf?pdfCanvasHtml(p):`<img src="${esc(p.imageUrl)}" loading="lazy" alt="Conteúdo do treinamento" onclick="openNativePage('${esc(p.imageUrl)}',${p.page})">`}</div><div class="student-page-floating-tools">${!usePdf?`<button class="student-tool-btn" onclick="openNativePage('${esc(p.imageUrl)}',${p.page})" title="Ampliar conteúdo">⛶ <span>Ampliar</span></button>`:''}${support?`<details class="student-support-popover"><summary>✦ <span>Pontos-chave</span></summary><div class="student-support-popover-body">${support}</div></details>`:''}</div><div class="student-page-number">Página ${p.page} de ${state.current?.payload?.source?.pages||'?'}</div></div>`}
function toggleStudentModules(){state.studentModulesCollapsed=!state.studentModulesCollapsed;render()}
function moduleQuizHtml(m,q,idx,total){const qid=q.id,name=`mq_student_${qid}`,saved=state.inlineAnswers[qid];return `<div class="module-quiz-card"><div class="module-quiz-heading"><span>QUIZ DO MÓDULO</span><strong>Pergunta ${idx+1} de ${total}</strong></div><h3>${esc(q.question)}</h3><div class="interactive-options">${(q.options||[]).map((o,i)=>`<label class="interactive-option ${saved?.selected===i?'selected':''}"><input type="radio" name="${name}" value="${i}" ${saved?.selected===i?'checked':''} onchange="selectModuleQuizOption('${qid}',${i})"><span><b>${String.fromCharCode(65+i)}</b>${esc(o)}</span></label>`).join('')}</div><button class="btn primary interaction-check" onclick="checkModuleQuiz('${qid}')">Verificar resposta</button><div id="mq_result_${qid}" class="checkpoint-result simple-feedback ${saved?.verified?(saved.correct?'good':'bad'):''}">${saved?.verified?(saved.correct?'<b>✅ Certo!</b>':'<b>❌ Errado</b>'):''}</div><div class="quiz-optional-note">Pergunta interativa: responder é opcional e não bloqueia o avanço.</div></div>`}
function selectModuleQuizOption(qid,selected){const prev=state.inlineAnswers[qid]||{};state.inlineAnswers[qid]={selected:Number(selected),verified:false,correct:prev.correct};saveStudentProgress();document.querySelectorAll(`input[name="mq_student_${qid}"]`).forEach((x,i)=>x.closest('label')?.classList.toggle('selected',i===Number(selected)));const out=$(`#mq_result_${qid}`);if(out){out.className='checkpoint-result simple-feedback';out.innerHTML='<span class="quiz-selection-hint">Alternativa selecionada. Clique em <b>Verificar resposta</b> para conferir.</span>'}}
function checkModuleQuiz(qid){const q=(state.current?.payload?.moduleQuizzes||[]).find(x=>x.id===qid)||(state.current?.payload?.questions||[]).find(x=>x.id===qid);if(!q)return;const chosen=document.querySelector(`input[name="mq_student_${qid}"]:checked`),out=$(`#mq_result_${qid}`);if(!chosen){out.className='checkpoint-result warn simple-feedback';out.textContent='Escolha uma alternativa para conferir.';return}const selected=Number(chosen.value),ok=selected===q.correctIndex;state.inlineAnswers[qid]={selected,correct:ok,verified:true};saveStudentProgress();if(out){out.className='checkpoint-result simple-feedback '+(ok?'good':'bad');out.innerHTML=ok?'<b>✅ Certo!</b>':'<b>❌ Errado</b>'}document.querySelectorAll(`input[name="mq_student_${qid}"]`).forEach((x,i)=>x.closest('label')?.classList.toggle('selected',i===selected))}
function nativeModuleDeck(m,{source=false,mode='preview'}={}){const slides=[{kind:'module-intro',label:'Início',title:m.learningTitle||m.title,topic:null,topicIndex:-1,html:moduleIntroHtml(m,{mode})}],allPages=(m.displayPages||m.sourcePages||[]).map(sourcePageByNumber).filter(p=>p?.imageUrl||pagePdfUrl(p)),pages=mode==='student'?allPages.filter(p=>p.role!=='CLOSING'):allPages,closingPages=mode==='student'?allPages.filter(p=>p.role==='CLOSING'):[];for(const p of pages){slides.push({kind:'source-page',label:'Conteúdo',title:p.title||m.learningTitle||m.title,topic:null,topicIndex:-1,pageData:p,topicLabel:p.title||'Conteúdo',html:mode==='student'?studentNativePageHtml(p):nativePageHtml(p)})}if(mode==='student'){const quiz=moduleQuizQuestions(m);if(quiz.length){quiz.slice(0,3).forEach((q,i)=>slides.push({kind:'module-quiz',label:'Quiz',title:'Quiz do módulo',topic:null,topicIndex:m.topics.length,interactionId:q.id,quizIndex:i,quizTotal:Math.min(3,quiz.length),html:moduleQuizHtml(m,q,i,Math.min(3,quiz.length))}))}for(const p of closingPages){slides.push({kind:'source-page',label:'Encerramento',title:p.title||'Encerramento',topic:null,topicIndex:-1,pageData:p,topicLabel:'Encerramento',html:studentNativePageHtml(p)})}return slides}else{for(const p of pages){for(const [ti,t] of m.topics.entries()){const src=(t.sourcePages||[]).map(Number);if(!src.length||Math.max(...src)!==Number(p.page)||!questionIsUseful(m,t))continue;(t.interactions||[]).slice(0,1).forEach((q,i)=>slides.push({kind:'interaction',label:'Interação',title:'Verifique o que observou',topic:t,topicIndex:ti,topicCardIndex:1,topicCardCount:1,topicLabel:t.learningTitle||t.title,interactionId:interactionKey(t,q,i),html:interactionHtml(t,q,mode,i)}))}}slides.push({kind:'module-end',label:'Resumo',title:'Módulo concluído',topic:null,topicIndex:m.topics.length,html:moduleEndHtml(m,{mode})});return slides}}
function legacyModuleDeck(m,{source=false,mode='preview'}={}){const slides=[{kind:'module-intro',label:'Início',title:m.learningTitle||m.title,topic:null,topicIndex:-1,html:moduleIntroHtml(m,{mode})}];m.topics.forEach((t,ti)=>{const cards=topicDeck(t,{source,mode,module:m});cards.forEach((c,ci)=>slides.push({...c,topic:t,topicIndex:ti,topicCardIndex:ci,topicCardCount:cards.length,topicLabel:t.learningTitle||t.title}))});if(mode!=='student')slides.push({kind:'module-end',label:'Resumo',title:'Módulo concluído',topic:null,topicIndex:m.topics.length,html:moduleEndHtml(m,{mode})});return slides}
function moduleDeck(m,{source=false,mode='preview'}={}){return state.current?.payload?.source?.nativePageMode?nativeModuleDeck(m,{source,mode}):legacyModuleDeck(m,{source,mode})}
function moduleIntroHtml(m,{mode='preview'}={}){const objectives=(m.learningObjectives||[]).filter(Boolean).slice(0,4);if(mode==='student')return `<div class="module-slide-intro student-clean-intro"><span class="module-slide-icon">▶</span><div class="micro-title">MÓDULO</div><h3>${esc(m.learningTitle||m.title)}</h3>${m.description?`<p class="module-slide-lead">${esc(m.description)}</p>`:''}${objectives.length?`<div class="module-objectives"><b>Neste módulo você vai:</b>${objectives.map(x=>`<div><span>✓</span><p>${esc(x)}</p></div>`).join('')}</div>`:''}<div class="module-start-hint">Quando estiver pronto, clique em <b>Começar módulo</b>.</div></div>`;return `<div class="module-slide-intro"><span class="module-slide-icon">▶</span><div class="micro-title">COMECE AQUI</div><h3>${esc(m.learningTitle||m.title)}</h3>${m.description?`<p class="module-slide-lead">${esc(m.description)}</p>`:''}<div class="module-slide-stats"><span><b>${m.topics.length}</b> assuntos</span><span><b>${(m.displayPages||m.sourcePages||[]).length}</b> páginas</span></div>${objectives.length?`<div class="module-objectives"><b>Ao final deste módulo você deverá:</b>${objectives.map(x=>`<div><span>✓</span><p>${esc(x)}</p></div>`).join('')}</div>`:''}<div class="module-start-hint">Clique em <b>Começar módulo</b> para avançar tela por tela.</div></div>`}
function moduleEndHtml(m,{mode='preview'}={}){const points=[];for(const t of m.topics){for(const x of (t.pedagogy?.remember||t.keyPoints||[])){if(x&&!points.includes(x))points.push(x);if(points.length>=5)break}if(points.length>=5)break}if(mode==='student'){const intro=isIntroModule(m);return `<div class="module-slide-end student-clean-end"><span class="module-slide-icon done">✓</span><div class="micro-title">MÓDULO CONCLUÍDO</div><h3>${esc(m.learningTitle||m.title)}</h3><p>${intro?'Você concluiu a introdução e já pode seguir para o próximo conteúdo.':'Você concluiu o conteúdo deste módulo.'}</p>${points.length?`<div class="module-recap"><b>Antes de seguir, lembre destes pontos:</b>${points.map(x=>`<div><span>✓</span><p>${esc(x)}</p></div>`).join('')}</div>`:''}</div>`}return `<div class="module-slide-end"><span class="module-slide-icon done">✓</span><div class="micro-title">MÓDULO CONCLUÍDO</div><h3>${esc(m.learningTitle||m.title)}</h3><p>Você percorreu todas as etapas deste módulo.</p>${points.length?`<div class="module-recap"><b>Antes de seguir, guarde estes pontos:</b>${points.map(x=>`<div><span>✓</span><p>${esc(x)}</p></div>`).join('')}</div>`:''}</div>`}
function moduleDeckCard(m,slides,current,{mode='preview'}={}){const s=slides[current]||slides[0];if(s.kind==='source-page'){const p=s.pageData;if(mode==='student')return `<div class="lesson-deck module-level-deck student-pdf-deck student-page-only"><div class="deck-stage student-pdf-stage">${s.html}</div></div>`;return `<div class="lesson-deck module-level-deck pdf-native-deck"><div class="deck-head native-deck-head"><div><span class="lesson-kicker">${pageRoleLabel(p.role).toUpperCase()} · PÁGINA ${p.page}</span><h2>${esc(s.title||`Página ${p.page} do material`)}</h2></div><div class="deck-counter">${p.page}<small>/ ${state.current?.payload?.source?.pages||'?'}</small></div></div><div class="deck-stage pdf-native-stage">${s.html}</div></div>`}if(s.kind==='module-quiz')return `<div class="lesson-deck module-level-deck student-quiz-deck"><div class="deck-head"><div><span class="lesson-kicker">QUIZ DO MÓDULO</span><h2>Confira o que você aprendeu</h2></div><div class="deck-counter">${s.quizIndex+1}<small>/ ${s.quizTotal}</small></div></div><div class="deck-stage question-stage">${s.html}</div></div>`;let kicker='MÓDULO';let sourceNote='';if(s.topic){kicker=`ASSUNTO ${s.topicIndex+1} DE ${m.topics.length} · ${typeTitle(s.topic.contentType)} · ${esc(s.label)}`;const display=s.topic.learningTitle||s.topic.title;if(display!==s.topic.title&&mode!=='student'){sourceNote=`<small class="source-title-note">No PDF: ${esc(s.topic.title)}</small>`}return `<div class="lesson-deck module-level-deck"><div class="deck-head"><div><span class="lesson-kicker">${kicker}</span><h2>${esc(s.title||display)}</h2>${sourceNote}</div><div class="deck-counter">${s.topicCardIndex+1}<small>/ ${s.topicCardCount}</small></div></div><div class="deck-stage ${s.kind==='interaction'?'question-stage':''}">${s.html}</div></div>`}kicker=s.kind==='module-end'?'FECHAMENTO DO MÓDULO':'ABERTURA DO MÓDULO';return `<div class="lesson-deck module-level-deck"><div class="deck-head"><div><span class="lesson-kicker">${kicker}</span><h2>${esc(s.title||m.learningTitle||m.title)}</h2></div><div class="deck-counter">${s.kind==='module-end'?'✓':'▶'}<small>${s.kind==='module-end'?'fim':'início'}</small></div></div><div class="deck-stage module-stage-special">${s.html}</div></div>`}
function moduleDots(slides,current,onclickName){const student=onclickName==='studentSetSlide';if(student){const pct=Math.round(((current+1)/Math.max(1,slides.length))*100);return `<div class="module-step-meter"><div><span>Etapa ${current+1} de ${slides.length}</span><b>${pct}%</b></div><div class="progress"><span style="width:${pct}%"></span></div></div>`}const max=18;if(slides.length<=max)return `<div class="deck-dots">${slides.map((s,i)=>`<button class="${i===current?'active':''}" title="${esc(s.topicLabel||s.label)}" onclick="${onclickName}(${i})"><span></span></button>`).join('')}</div>`;const pct=Math.round(((current+1)/slides.length)*100);return `<div class="module-step-meter"><div><span>Etapa ${current+1} de ${slides.length}</span><b>${pct}%</b></div><div class="progress"><span style="width:${pct}%"></span></div></div>`}
function slideCanAdvance(slide,mode='student'){return true}
function previewSetSlide(i){const m=selected(),slides=moduleDeck(m,{source:true,mode:'preview'});state.previewSlide=Math.max(0,Math.min(i,slides.length-1));render()}
function previewMove(delta){const m=selected(),slides=moduleDeck(m,{source:true,mode:'preview'});state.previewSlide=Math.max(0,Math.min(slides.length-1,state.previewSlide+delta));render()}
function studentProgressKey(){return state.current?.id?`fortix_student_progress_${state.current.id}_${studentIdentityKey()}`:null}
function saveStudentProgress(){const key=studentProgressKey();if(!key)return;try{localStorage.setItem(key,JSON.stringify({moduleId:state.studentModule,slide:state.studentSlide,inlineAnswers:state.inlineAnswers,viewedSteps:state.viewedSteps,completedModules:state.completedModules,assessmentAnswers:state.answers,assessmentAttempts:state.assessmentAttempts,assessmentPassed:state.assessmentPassed,lastScore:state.lastScore,certificateInfo:state.certificateInfo,studentProfile:state.studentProfile,updatedAt:Date.now()}))}catch{}}
function loadStudentProgress(){const key=studentProgressKey();if(!key)return null;try{return JSON.parse(localStorage.getItem(key)||'null')}catch{return null}}
function clearStudentProgress(){const key=studentProgressKey();if(key)try{localStorage.removeItem(key)}catch{}}
function completedSet(){return new Set(state.completedModules||[])}
function currentStudentStepKey(){return `${state.studentModule||''}:${Math.max(0,Number(state.studentSlide)||0)}`}
function currentStudentSlide(){const p=state.current?.payload,mods=p?.modules||[],m=mods.find(x=>x.id===state.studentModule)||mods[0];if(!m)return null;return moduleDeck(m,{source:false,mode:'student'})[Math.max(0,Number(state.studentSlide)||0)]||null}
function studentPageIsOrientation(p){if(!p)return true;const role=String(p.role||'').toUpperCase();if(['COVER','AGENDA','CLOSING'].includes(role))return true;const raw=[p.title,p.text,(p.learning?.topics||[]).join(' ')].filter(Boolean).join(' '),n=plainNorm(raw);return ['introducao','objetivo','objetivos','apresentacao','roteiro','sumario','boas vindas','conteudo programatico','finalidade do treinamento','visao geral'].some(k=>n.includes(k))}
function studentStepRequiredMs(){const s=currentStudentSlide();if(!s||s.kind!=='source-page')return 0;return studentPageIsOrientation(s.pageData)?0:STUDENT_CONTENT_STEP_MS}
function ensureStudentStepTimer(){const key=currentStudentStepKey(),required=studentStepRequiredMs();if(required<=0){state.viewedSteps=state.viewedSteps||{};if(!state.viewedSteps[key]){state.viewedSteps[key]=Date.now();saveStudentProgress()}state.activeStudentStepKey=key;state.studentStepStartedAt=0;return}if(state.viewedSteps?.[key]){state.activeStudentStepKey=key;return}if(state.activeStudentStepKey!==key||!state.studentStepStartedAt){state.activeStudentStepKey=key;state.studentStepStartedAt=Date.now()}}
function studentStepRemainingMs(){const key=currentStudentStepKey(),required=studentStepRequiredMs();if(required<=0)return 0;if(state.viewedSteps?.[key])return 0;ensureStudentStepTimer();const remaining=Math.max(0,required-(Date.now()-state.studentStepStartedAt));if(remaining<=0){state.viewedSteps=state.viewedSteps||{};state.viewedSteps[key]=Date.now();saveStudentProgress();return 0}return remaining}
function studentStepReady(){return studentStepRemainingMs()<=0}
function refreshStudentAdvanceTimer(){if(studentAdvanceTimer){clearInterval(studentAdvanceTimer);studentAdvanceTimer=null}if(state.route!=='student-course')return;const update=()=>{if(state.route!=='student-course'){if(studentAdvanceTimer){clearInterval(studentAdvanceTimer);studentAdvanceTimer=null}return}const required=studentStepRequiredMs(),remaining=studentStepRemainingMs(),ready=remaining<=0,btn=document.querySelector('#studentNextBtn'),note=document.querySelector('#studentAdvanceNote');if(btn){btn.disabled=!ready;btn.classList.toggle('locked',!ready);btn.textContent=ready?(btn.dataset.readyLabel||'Continuar →'):`Aguarde ${Math.max(1,Math.ceil(remaining/1000))}s`}if(note){note.innerHTML=!required?'<span class="step-ready subtle">Avance quando quiser</span>':ready?'<span class="step-ready">✓ Você já pode continuar</span>':`<span class="step-wait">Observe esta página por mais <b>${Math.max(1,Math.ceil(remaining/1000))}s</b></span>`}if(ready&&studentAdvanceTimer){clearInterval(studentAdvanceTimer);studentAdvanceTimer=null}};update();if(studentStepRemainingMs()>0)studentAdvanceTimer=setInterval(update,250)}
function unlockedModuleIndex(mods){const done=completedSet();let idx=0;while(idx<mods.length&&done.has(mods[idx].id))idx++;return Math.min(idx,Math.max(0,mods.length-1))}
function studentSetSlide(i){const p=state.current.payload,m=p.modules.find(x=>x.id===state.studentModule)||p.modules[0],slides=moduleDeck(m,{source:false,mode:'student'}),target=Math.max(0,Math.min(i,slides.length-1));if(target>state.studentSlide&&!studentStepReady()){toast(`Aguarde ${Math.max(1,Math.ceil(studentStepRemainingMs()/1000))}s para continuar.`);return}state.studentSlide=target;saveStudentProgress();render()}
function totalStudentSlides(mods){return mods.reduce((sum,m)=>sum+moduleDeck(m,{source:false,mode:'student'}).length,0)}
function studentProgress(mods,m,slide){const done=completedSet(),total=totalStudentSlides(mods);let progress=0;for(const mm of mods){const n=moduleDeck(mm,{source:false,mode:'student'}).length;if(done.has(mm.id)){progress+=n;continue}if(mm.id===m.id){progress+=Math.min(n,Math.max(0,slide));break}}return Math.min(100,Math.round((progress/Math.max(1,total))*100))}
function markModuleCompleted(id){if(!state.completedModules.includes(id))state.completedModules.push(id)}
function studentMove(delta){const p=state.current.payload,mods=p.modules,m=mods.find(x=>x.id===state.studentModule)||mods[0],slides=moduleDeck(m,{source:false,mode:'student'}),mi=mods.indexOf(m);if(delta>0&&!studentStepReady()){toast(`Aguarde ${Math.max(1,Math.ceil(studentStepRemainingMs()/1000))}s para continuar.`);return}let next=state.studentSlide+delta;if(next>=0&&next<slides.length){state.studentSlide=next;saveStudentProgress();render();return}if(delta>0){markModuleCompleted(m.id);if(mi<mods.length-1){const nm=mods[mi+1];state.studentModule=nm.id;state.studentSlide=0;saveStudentProgress();render();return}saveStudentProgress();materialsView();return}if(delta<0&&mi>0){const pm=mods[mi-1],ps=moduleDeck(pm,{source:false,mode:'student'});state.studentModule=pm.id;state.studentSlide=ps.length-1;saveStudentProgress();render()}}
function previewView(){const p=state.current.payload,m=selected();if(!m)return '';const slides=moduleDeck(m,{source:true,mode:'preview'});state.previewSlide=Math.min(state.previewSlide,Math.max(0,slides.length-1));const s=slides[state.previewSlide],midx=p.modules.indexOf(m),topicText=s.kind==='source-page'?`Página ${s.pageData.page} do PDF`:s.topic?`Assunto ${s.topicIndex+1} de ${m.topics.length}`:(s.kind==='module-intro'?'Abertura':'Fechamento');setHeader('Preview do treinamento','Veja como o aluno vai navegar pelas aulas interativas geradas a partir do material enviado.');return `<div class="content">${steps(4)}<div class="interactive-workbench v07"><aside class="card sticky deck-sidebar"><div class="card-head"><b>Módulos do curso</b></div><div class="card-body"><div class="module-progress"><span>Módulo ${midx+1} de ${p.modules.length}</span><b>${m.topics.length} assunto(s)</b></div><div class="module-list mt">${p.modules.map((x,i)=>`<button class="module-item ${x.id===m.id?'active':''}" onclick="selectModule('${x.id}')" style="text-align:left"><b>${i+1}. ${esc(x.learningTitle||x.title)}</b><small>${x.topics.length} assuntos</small></button>`).join('')}</div></div></aside><main class="deck-main"><div class="module-minihero"><div><span>MÓDULO ${midx+1} DE ${p.modules.length} · ${esc(topicText)}</span><h2>${esc(m.learningTitle||m.title)}</h2><p>Este preview simula a experiência do aluno com aula, explicação, prática, atenção, checklist e pergunta rápida.</p></div><button class="btn dark" onclick="studentMode('${state.current.id}')">▶ Como aluno</button></div>${moduleDeckCard(m,slides,state.previewSlide,{mode:'preview'})}<div class="deck-footer"><button class="btn outline" ${state.previewSlide===0?'disabled':''} onclick="previewMove(-1)">← Anterior</button>${moduleDots(slides,state.previewSlide,'previewSetSlide')}<button class="btn primary" ${state.previewSlide===slides.length-1?'disabled':''} onclick="previewMove(1)">${state.previewSlide===0?'Começar módulo →':'Próximo →'}</button></div></main><aside class="card sticky deck-outline v07-outline"><div class="card-head"><b>Progresso do módulo</b></div><div class="card-body"><div class="module-stage-summary"><strong>${Math.round(((state.previewSlide+1)/slides.length)*100)}%</strong><span>do módulo</span></div><div class="progress mt"><span style="width:${Math.round(((state.previewSlide+1)/slides.length)*100)}%"></span></div><div class="v07-current-topic mt"><small>ETAPA ATUAL</small><b>${esc(s.topicLabel||s.label)}</b><span>${esc(s.label)}</span></div><div class="notice info mt">No teste como aluno, o preview abre direto sem pedir dados pessoais. A navegação mostra as aulas interativas do treinamento, não uma página PDF gerada.</div></div></aside></div><div class="toolbar"><button class="btn outline" onclick="goStep(3)">← Estrutura</button><button class="btn primary" onclick="goStep(5)">Revisar e editar →</button></div></div>`}
function studentSelectModule(id){const p=state.current.payload,mods=p.modules,idx=mods.findIndex(x=>x.id===id),m=mods[idx];if(!m)return;const unlocked=unlockedModuleIndex(mods),done=completedSet();if(idx>unlocked&&!done.has(id)){toast('Conclua os módulos anteriores para liberar este conteúdo.');return}state.studentModule=id;state.studentSlide=0;saveStudentProgress();render()}
function reviewTopicEditor(t,i){
  const types=['GENERAL_CONTENT','DEFINITION','BENEFIT','CONSEQUENCE','PRACTICE','OBLIGATION','PROHIBITION','RISK','PROCEDURE','EPI','EPC','EMERGENCY','RESPONSIBILITY','LEGAL_REFERENCE'];
  const origins=['SOURCE','ADAPTED','GENERATED'];
  const title=t.learningTitle||t.pedagogy?.learningTitle||t.title;
  return `<details class="topic-edit topic-accordion" data-topic="${t.id}">
    <summary class="topic-edit-head">
      <div><span class="topic-number">${i+1}</span><span><b>${esc(title)}</b><small>Páginas ${range(t.sourcePages)} · ${esc(t.contentType||'GENERAL_CONTENT')}</small></span></div>
      <span class="topic-open-label">Editar ▾</span>
    </summary>
    <div class="topic-edit-body">
      <div class="form-row mt"><div class="field"><label>Título de origem</label><input class="t-title" value="${esc(t.title)}"></div><div class="field"><label>Título didático</label><input class="t-learning-title" value="${esc(title)}"></div></div>
      <div class="form-row mt"><div class="field"><label>Tipo didático</label><select class="t-type">${types.map(x=>`<option ${x===t.contentType?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Origem</label><select class="t-origin">${origins.map(x=>`<option ${x===t.origin?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Fonte</label><input value="Páginas ${range(t.sourcePages)}" disabled></div></div>
      <div class="field mt"><label>Explicação em linguagem direta</label><textarea class="t-simple" rows="4">${esc(t.pedagogy?.simpleExplanation||t.summary||'')}</textarea></div>
      <div class="field mt"><label>Aplicação prática</label><textarea class="t-practice" rows="3">${esc(t.pedagogy?.practicalApplication||'')}</textarea></div>
      <div class="field mt"><label>Resumo de origem</label><textarea class="t-summary" rows="3">${esc(t.summary||'')}</textarea></div>
      <div class="field mt"><label>Pontos-chave <small class="muted">(um por linha)</small></label><textarea class="t-keypoints" rows="4">${esc((t.keyPoints||[]).join('\n'))}</textarea></div>
      <details class="advanced-source-edit mt"><summary>Conteúdo técnico / fonte</summary><div class="field mt"><label>Conteúdo-base extraído</label><textarea class="t-content" rows="7">${esc(t.content||'')}</textarea></div><div class="editor-actions"><span class="muted">Páginas ${range(t.sourcePages)} · confiança ${Math.round((t.confidence||0)*100)}%</span>${sourceButton(t)}</div></details>
      <div class="topic-danger-row"><button class="btn danger" onclick="event.preventDefault();removeTopic('${t.id}')">Excluir tópico</button></div>
    </div>
  </details>`;
}
function reviewView(){
  const p=state.current.payload,m=selected(); if(!m)return '';
  const mi=p.modules.indexOf(m),mq=(p.moduleQuizzes||[]).filter(q=>q.moduleId===m.id),fq=(p.questions||[]).filter(q=>q.moduleId===m.id);
  setHeader('Revisão e ajustes','Revise um módulo por vez. Os detalhes técnicos ficam recolhidos para não poluir a revisão.');
  return `<div class="content">${steps(5)}<div class="editor">
    <div class="card sticky"><div class="card-head"><b>Módulos</b><a class="btn outline" href="/api/projects/${state.current.id}/export">Backup</a></div><div class="card-body module-list">${p.modules.map((x,i)=>`<button class="module-item ${x.id===m.id?'active':''}" onclick="selectModule('${x.id}')" style="text-align:left"><b>${i+1}. ${esc(x.learningTitle||x.title)}</b><small>Páginas ${range(x.displayPages||x.sourcePages)} · ${x.topics.length} tópicos · ${(p.moduleQuizzes||[]).filter(q=>q.moduleId===x.id).length} quiz</small></button>`).join('')}<button class="btn soft mt" onclick="addModule()">＋ Adicionar módulo</button></div></div>
    <div class="card"><div class="card-head"><b>Editor do módulo</b><span class="badge published">Motor V1.6.0</span></div><div class="editor-panel">
      <div class="module-admin-actions"><button class="btn outline" ${mi===0?'disabled':''} onclick="moveModule(-1)">↑ Mover</button><button class="btn outline" ${mi===p.modules.length-1?'disabled':''} onclick="moveModule(1)">↓ Mover</button><button class="btn soft" ${mi===p.modules.length-1?'disabled':''} onclick="mergeWithNext()">Unir com próximo</button></div>
      <div class="form-row mt"><div class="field"><label>Título de origem</label><input id="mTitle" value="${esc(m.title)}"></div><div class="field"><label>Título didático</label><input id="mLearningTitle" value="${esc(m.learningTitle||m.title)}"></div></div>
      <div class="field mt"><label>Introdução do módulo</label><textarea id="mDesc" rows="3">${esc(m.description||'')}</textarea></div>
      <div class="field mt"><label>Objetivos de aprendizagem <small class="muted">(um por linha)</small></label><textarea id="mObjectives" rows="3">${esc((m.learningObjectives||[]).join('\n'))}</textarea></div>
      <div class="editor-section-header"><div><h4>Tópicos do módulo</h4><small>${m.topics.length} tópico(s). Abra somente o que precisa revisar.</small></div><button class="btn soft" onclick="addTopic()">＋ Adicionar tópico</button></div>
      <div id="topicEditors" class="topic-accordion-list">${m.topics.map((t,i)=>reviewTopicEditor(t,i)).join('')}</div>
      <div class="toolbar"><button class="btn outline" onclick="goStep(4)">← Preview</button><button class="btn primary" onclick="saveModuleEdits()">Salvar módulo</button></div>
    </div></div>
    <div class="card sticky"><div class="card-head"><b>Controle do módulo</b></div><div class="card-body">
      <div class="check">▣ <span><b>${(m.displayPages||m.sourcePages||[]).length}</b> páginas no player</span></div>
      <div class="check">✓ <span><b>${m.topics.length}</b> tópicos</span></div>
      <div class="check"><span><b>${mq.length}</b> pergunta(s) no quiz do módulo</span></div>
      <div class="check"><span><b>${fq.length}</b> questão(ões) na avaliação final</span></div>
      <button class="btn outline mt" style="width:100%" onclick="showModuleQuizzes()">Editar quiz do módulo</button><button class="btn outline mt" style="width:100%" onclick="showQuestions()">Editar avaliação final</button>
      <div class="notice info mt">Se houver divisão excessiva, use <b>Unir com próximo</b>. Antes de publicar, revise principalmente títulos, ordem dos módulos e perguntas.</div>
    </div></div>
  </div><div class="toolbar"><span></span><button class="btn primary" onclick="saveAndPublishStep()">Salvar e ir para publicação →</button></div></div>`;
}
function collectModuleEdits(){
  const m=selected(); if(!m||!document.querySelector('#mTitle'))return;
  m.title=$('#mTitle').value.trim()||m.title;
  m.learningTitle=$('#mLearningTitle').value.trim()||m.title;
  m.description=$('#mDesc').value.trim();
  m.learningObjectives=$('#mObjectives').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);
  document.querySelectorAll('#topicEditors .topic-edit').forEach(el=>{
    const t=m.topics.find(x=>x.id===el.dataset.topic); if(!t)return;
    const val=(sel)=>el.querySelector(sel)?.value??'';
    t.title=val('.t-title').trim()||t.title;
    t.learningTitle=val('.t-learning-title').trim()||t.title;
    t.contentType=val('.t-type')||t.contentType||'GENERAL_CONTENT';
    t.origin=val('.t-origin')||t.origin||'SOURCE';
    t.summary=val('.t-summary').trim();
    t.content=val('.t-content');
    t.keyPoints=val('.t-keypoints').split(/\n+/).map(x=>x.trim()).filter(Boolean);
    t.pedagogy=t.pedagogy||{};
    t.pedagogy.learningTitle=t.learningTitle;
    t.pedagogy.simpleExplanation=val('.t-simple').trim();
    t.pedagogy.practicalApplication=val('.t-practice').trim();
    t.pedagogy.origin=t.origin;
  });
  state.current.payload.quality={};
}
async function saveCurrent(){collectModuleEdits();state.current=await api(`/api/projects/${state.current.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({payload:state.current.payload})});await loadProjects()}
async function saveModuleEdits(){await saveCurrent();toast('Alterações salvas.');render()}
function addTopic(){collectModuleEdits();const m=selected();m.topics.push({id:crypto.randomUUID(),title:'Novo tópico',learningTitle:'Novo tópico',content:'Edite o conteúdo deste tópico.',summary:'Defina um resumo curto para orientar o aluno.',paragraphs:['Edite o conteúdo deste tópico.'],keyPoints:['Defina o principal ponto que o aluno deve guardar.'],steps:[],callout:null,checkpoint:null,activity:{title:'Conecte com a prática',prompt:'Relacione este conteúdo com uma situação da sua atividade.'},readingMinutes:1,contentType:'GENERAL_CONTENT',origin:'GENERATED',pedagogy:{learningTitle:'Novo tópico',opening:'Apresente por que este assunto é importante para o aluno.',simpleExplanation:'Explique este conteúdo em linguagem simples.',focusTitle:'O que você precisa guardar',remember:['Defina o principal ponto que o aluno deve guardar.'],practicalApplication:'Relacione este conteúdo com uma situação real da atividade.',glossary:[],legalReferences:[],learningGoal:'Defina o objetivo de aprendizagem deste tópico.',origin:'GENERATED'},sourcePages:[],confidence:1});render()}
function removeTopic(id){collectModuleEdits();const m=selected();m.topics=m.topics.filter(t=>t.id!==id);render()}
function addModule(){collectModuleEdits();const m={id:crypto.randomUUID(),title:'Novo módulo',learningTitle:'Novo módulo',description:'',learningObjectives:['Defina o objetivo de aprendizagem deste módulo.'],keyPoints:[],sourcePages:[],confidence:1,estimatedMinutes:5,topics:[]};state.current.payload.modules.push(m);state.selectedModule=m.id;render()}
function moveModule(delta){collectModuleEdits();const mods=state.current.payload.modules,m=selected(),i=mods.indexOf(m),j=i+delta;if(j<0||j>=mods.length)return;[mods[i],mods[j]]=[mods[j],mods[i]];mods.forEach((x,k)=>x.displayOrder=k);state.current.payload.quality={};render()}
function mergeWithNext(){collectModuleEdits();const p=state.current.payload,mods=p.modules,m=selected(),i=mods.indexOf(m);if(i<0||i>=mods.length-1)return;const n=mods[i+1];if(!confirm(`Unir “${m.learningTitle||m.title}” com “${n.learningTitle||n.title}”?`))return;m.topics=[...(m.topics||[]),...(n.topics||[])];m.sourcePages=[...new Set([...(m.sourcePages||[]),...(n.sourcePages||[])].map(Number))].sort((a,b)=>a-b);m.displayPages=[...new Set([...(m.displayPages||m.sourcePages||[]),...(n.displayPages||n.sourcePages||[])].map(Number))].sort((a,b)=>a-b);m.sourceStartPage=Math.min(...(m.sourcePages.length?m.sourcePages:[1]));m.sourceEndPage=Math.max(...(m.sourcePages.length?m.sourcePages:[1]));m.sourceWordCount=(m.sourceWordCount||0)+(n.sourceWordCount||0);m.sourceVisualCount=(m.sourceVisualCount||0)+(n.sourceVisualCount||0);m.learningObjectives=[...new Set([...(m.learningObjectives||[]),...(n.learningObjectives||[])])].slice(0,6);m.keyPoints=[...new Set([...(m.keyPoints||[]),...(n.keyPoints||[])])].slice(0,12);for(const q of [...(p.moduleQuizzes||[]),...(p.questions||[])])if(q.moduleId===n.id)q.moduleId=m.id;mods.splice(i+1,1);mods.forEach((x,k)=>x.displayOrder=k);p.quality={};render();toast('Módulos unidos. Revise o título e os objetivos.')}
function questionEditorRows(items,kind){return items.length?items.map((q,qi)=>`<div class="question" data-${kind}="${q.id}"><div class="field"><label>Pergunta ${qi+1}</label><textarea class="q-text" rows="2">${esc(q.question)}</textarea></div>${(q.options||[]).map((o,i)=>`<div class="field mt"><label>Alternativa ${i+1} ${i===q.correctIndex?'✓ correta':''}</label><input class="q-opt" data-i="${i}" value="${esc(o)}"></div>`).join('')}<div class="field mt"><label>Resposta correta</label><select class="q-correct">${(q.options||[]).map((_,i)=>`<option value="${i}" ${i===q.correctIndex?'selected':''}>Alternativa ${i+1}</option>`).join('')}</select></div><div class="field mt"><label>Explicação</label><textarea class="q-exp" rows="2">${esc(q.explanation||'')}</textarea></div><div class="project-meta mt">Fonte: páginas ${range(q.sourcePages||[])} · ${esc(q.origin||'')}</div><button class="btn danger mt" onclick="${kind==='mq'?'deleteModuleQuiz':'deleteQuestion'}('${q.id}')">Excluir questão</button></div>`).join(''):'<div class="empty">Nenhuma pergunta configurada neste módulo.</div>'}
function showModuleQuizzes(){collectModuleEdits();const p=state.current.payload,m=selected(),items=(p.moduleQuizzes||[]).filter(q=>q.moduleId===m.id);modal(`<h3>Quiz do módulo — ${esc(m.learningTitle||m.title)}</h3><p class="muted">Estas perguntas aparecem somente no fechamento deste módulo.</p>${questionEditorRows(items,'mq')}<div class="toolbar"><button class="btn soft" onclick="addModuleQuiz('${m.id}')">＋ Adicionar pergunta</button><button class="btn primary" onclick="saveModuleQuizzes()">Salvar quiz</button></div>`,'Quiz do módulo')}
function saveModuleQuizzes(){const p=state.current.payload;$$('.question[data-mq]').forEach(el=>{const q=(p.moduleQuizzes||[]).find(x=>x.id===el.dataset.mq);if(!q)return;q.question=el.querySelector('.q-text').value;q.options=[...el.querySelectorAll('.q-opt')].map(x=>x.value);q.correctIndex=Number(el.querySelector('.q-correct').value);q.explanation=el.querySelector('.q-exp').value});closeModal();saveCurrent().then(()=>toast('Quiz do módulo salvo.'))}
function deleteModuleQuiz(id){state.current.payload.moduleQuizzes=(state.current.payload.moduleQuizzes||[]).filter(q=>q.id!==id);showModuleQuizzes()}
function addModuleQuiz(mid){const p=state.current.payload,m=p.modules.find(x=>x.id===mid),t=m.topics[0];p.moduleQuizzes=p.moduleQuizzes||[];p.moduleQuizzes.push({id:crypto.randomUUID(),moduleId:mid,topicId:t?.id||null,type:'multiple_choice',question:'Nova pergunta do módulo',options:['Alternativa correta','Alternativa 2','Alternativa 3','Alternativa 4'],correctIndex:0,explanation:'Explique a resposta usando o conteúdo do módulo.',difficulty:'média',sourcePages:(t?.sourcePages||m.sourcePages||[]).slice(0,2),origin:'GENERATED'});showModuleQuizzes()}

async function saveAndPublishStep(){await saveCurrent();goStep(6)}
function showQuestions(){collectModuleEdits();const p=state.current.payload,m=selected(),qs=p.questions.filter(q=>q.moduleId===m.id);modal(`<h3>Avaliação final — ${esc(m.learningTitle||m.title)}</h3><p class="muted">Estas questões entram somente na avaliação final do treinamento.</p>${questionEditorRows(qs,'q')}<div class="toolbar"><button class="btn soft" onclick="addQuestion('${m.id}')">＋ Adicionar questão</button><button class="btn primary" onclick="saveQuestions()">Salvar questões</button></div>`,'Editor de avaliação')}
function saveQuestions(){const p=state.current.payload;$$('.question[data-q]').forEach(el=>{const q=p.questions.find(x=>x.id===el.dataset.q);q.question=el.querySelector('.q-text').value;q.options=[...el.querySelectorAll('.q-opt')].map(x=>x.value);q.correctIndex=Number(el.querySelector('.q-correct').value);q.explanation=el.querySelector('.q-exp').value});closeModal();saveCurrent().then(()=>toast('Questões salvas.'))}
function deleteQuestion(id){state.current.payload.questions=state.current.payload.questions.filter(q=>q.id!==id);showQuestions()}
function addQuestion(mid){const m=state.current.payload.modules.find(x=>x.id===mid);state.current.payload.questions.push({id:crypto.randomUUID(),moduleId:mid,topicId:m.topics[0]?.id||null,type:'multiple_choice',question:'Nova pergunta',options:['Alternativa correta','Alternativa 2','Alternativa 3','Alternativa 4'],correctIndex:0,explanation:'Explique por que a alternativa está correta.',difficulty:'média',sourcePages:m.sourcePages.slice(0,2),origin:'GENERATED'});showQuestions()}
function materialsAdminHtml(p){const items=p.materials||[];return `<div class="card"><div class="card-head"><b>Materiais complementares</b><span class="badge type">${items.length}</span></div><div class="card-body"><p class="muted">Arquivos disponibilizados ao aluno no fim do treinamento, antes da avaliação final.</p><div class="form-row"><div class="field"><label>Título do material</label><input id="materialTitle" placeholder="Ex.: Apostila de apoio"></div><div class="field"><label>Arquivo</label><input id="materialFile" type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.png,.jpg,.jpeg,.zip"></div></div><button class="btn outline mt" onclick="uploadMaterial()">＋ Adicionar material</button><div class="material-admin-list mt">${items.length?items.map(x=>`<div class="material-admin-row"><div><b>${esc(x.title||x.filename)}</b><small>${esc(x.filename)} · ${fmtBytes(x.size||0)}</small></div><div><a class="btn outline compact" href="/api/projects/${state.current.id}/materials/${x.id}">Baixar</a><button class="btn danger compact" onclick="deleteMaterial('${x.id}')">Excluir</button></div></div>`).join(''):'<div class="empty">Nenhum material complementar adicionado.</div>'}</div></div></div>`}
function publishView(){const p=state.current.payload,q=p.quality||{errors:[],warnings:[],info:[]},cs=p.certificateSettings||{};setHeader('Revisão final e publicação','Configure materiais, avaliação e certificado antes de disponibilizar.');return `<div class="content">${steps(6)}${state.current.status==='PUBLISHED'?`<div class="card success-panel"><div class="success-icon">✓</div><h2>Treinamento publicado</h2><p class="muted">${esc(p.title)} está disponível no modo aluno.</p><div class="grid cols4 mt"><div class="stat"><span class="label">MÓDULOS</span><strong>${p.modules.length}</strong></div><div class="stat"><span class="label">MATERIAIS</span><strong>${(p.materials||[]).length}</strong></div><div class="stat"><span class="label">QUESTÕES</span><strong>${p.questions.length}</strong></div><div class="stat"><span class="label">QUIZZES</span><strong>${(p.moduleQuizzes||[]).length}</strong></div></div><div class="toolbar"><button class="btn outline" onclick="setRoute('library')">← Treinamentos</button><a class="btn outline" href="/api/projects/${state.current.id}/export">Baixar backup</a><button class="btn dark" onclick="startStudentCourse('${state.current.id}')">▶ Abrir como aluno</button></div></div>${materialsAdminHtml(p)}`:`<div class="publish-layout"><div class="card"><div class="card-head"><b>Informações</b></div><div class="card-body"><div class="field"><label>Título</label><input id="pTitle" value="${esc(p.title)}"></div><div class="field mt"><label>Categoria</label><input id="pCategory" value="${esc(p.category)}"></div><div class="field mt"><label>Público-alvo</label><input id="pAudience" value="${esc(p.audience)}"></div><div class="form-row mt"><div class="field"><label>Carga horária (h)</label><input id="pHours" type="number" step="0.1" value="${p.estimatedHours}"></div><div class="field"><label>Nota mínima %</label><input id="pScore" type="number" value="${p.passingScore}"></div><div class="field"><label>Tentativas</label><input id="pAttempts" type="number" value="${p.attempts}"></div></div></div></div><div class="card"><div class="card-head"><b>Quality gate</b><button class="btn outline" onclick="runQuality()">Executar</button></div><div class="card-body">${qualityHtml(q)}${!q.errors?.length&&!q.warnings?.length?'<div class="empty">Execute a validação final.</div>':''}</div></div>${materialsAdminHtml(p)}<div class="card"><div class="card-head"><b>Certificado</b></div><div class="card-body"><label class="check"><input id="pCert" type="checkbox" ${p.certificate?'checked':''}><span>Emitir certificado após aprovação</span></label><div class="field mt"><label>Emissor</label><input id="pCertIssuer" value="${esc(cs.issuer||'FortixSeg')}"></div><div class="form-row mt"><div class="field"><label>Responsável</label><input id="pCertResponsible" value="${esc(cs.responsibleName||'')}" placeholder="Nome do responsável"></div><div class="field"><label>Função</label><input id="pCertRole" value="${esc(cs.responsibleRole||'')}" placeholder="Ex.: Instrutor / Responsável técnico"></div></div><div class="notice info mt">O certificado usa nome do aluno, treinamento, carga horária, nota, data, código único e QR Code de validação.</div></div></div><div class="card"><div class="card-head"><b>Publicação</b></div><div class="card-body"><div class="field"><label>Visibilidade</label><select id="pVisibility"><option value="private" ${p.visibility==='private'?'selected':''}>Privado</option><option value="groups" ${p.visibility==='groups'?'selected':''}>Grupos</option><option value="public" ${p.visibility==='public'?'selected':''}>Público</option></select></div><div class="notice warn mt">Publicar disponibiliza o treinamento no modo aluno deste ambiente local.</div><button class="btn success mt" style="width:100%" onclick="publishProject()">✓ Publicar treinamento</button></div></div></div><div class="toolbar"><button class="btn outline" onclick="goStep(5)">← Revisão</button><button class="btn soft" onclick="savePublishFields()">Salvar como rascunho</button></div>`}</div>`}
function qualityHtml(q){return [...(q.errors||[]).map(x=>`<div class="quality-item error"><span class="dot">!</span><span>${esc(x)}</span></div>`),...(q.warnings||[]).map(x=>`<div class="quality-item warning"><span class="dot">!</span><span>${esc(x)}</span></div>`),...(q.info||[]).map(x=>`<div class="quality-item info"><span class="dot">i</span><span>${esc(x)}</span></div>`)].join('')}
function collectPublish(){const p=state.current.payload;if(!$('#pTitle'))return;p.title=$('#pTitle').value;p.category=$('#pCategory').value;p.audience=$('#pAudience').value;p.estimatedHours=Number($('#pHours').value)||.5;p.passingScore=Number($('#pScore').value)||70;p.attempts=Number($('#pAttempts').value)||1;p.visibility=$('#pVisibility').value;p.certificate=$('#pCert')?.checked??p.certificate;p.certificateSettings={issuer:$('#pCertIssuer')?.value||'FortixSeg',responsibleName:$('#pCertResponsible')?.value||'',responsibleRole:$('#pCertRole')?.value||'',verificationEnabled:true}}
async function savePublishFields(){collectPublish();await saveCurrent();toast('Rascunho salvo.');render()}
async function runQuality(){collectPublish();await saveCurrent();const q=await api(`/api/projects/${state.current.id}/quality`,{method:'POST'});state.current.payload.quality=q;toast(q.canPublish?'Validação concluída.':'Há erros que bloqueiam a publicação.');render()}
async function publishProject(){collectPublish();await saveCurrent();const q=await api(`/api/projects/${state.current.id}/quality`,{method:'POST'});state.current.payload.quality=q;if(!q.canPublish){toast('Corrija os erros antes de publicar.');render();return}try{state.current=await api(`/api/projects/${state.current.id}/publish`,{method:'POST'});await loadProjects();render();toast('Treinamento publicado!')}catch(e){toast(e.message)}}
async function uploadMaterial(){const input=$('#materialFile'),file=input?.files?.[0];if(!file){toast('Selecione um arquivo.');return}const fd=new FormData();fd.append('file',file);fd.append('title',$('#materialTitle')?.value||'');try{await api(`/api/projects/${state.current.id}/materials`,{method:'POST',body:fd});state.current=await api(`/api/projects/${state.current.id}`);toast('Material adicionado.');render()}catch(e){toast('Erro: '+e.message)}}
async function deleteMaterial(id){if(!confirm('Excluir este material complementar?'))return;await api(`/api/projects/${state.current.id}/materials/${id}`,{method:'DELETE'});state.current=await api(`/api/projects/${state.current.id}`);toast('Material removido.');render()}
function studentList(){setHeader('Modo aluno','Treinamentos publicados disponíveis para realização.');const pubs=state.projects.filter(p=>p.status==='PUBLISHED'),profile=loadStudentProfile();return `<div class="content"><div class="section-title"><div><h3>Treinamentos disponíveis</h3><p>${profile?.name?`Aluno: <b>${esc(profile.name)}</b> · <button class="link-btn" onclick="editStudentProfile()">editar dados</button>`:'Antes de iniciar, o aluno informa seus dados para registro e certificado.'}</p></div></div><div class="grid cols3">${pubs.length?pubs.map(p=>`<div class="card"><div class="card-body"><span class="badge published">Disponível</span><h3>${esc(p.title)}</h3><p class="muted">${p.modules} módulos</p><button class="btn primary" onclick="startStudentCourse('${p.id}')">Iniciar treinamento →</button></div></div>`).join(''):'<div class="card"><div class="empty">Nenhum treinamento publicado ainda.</div></div>'}</div></div>`}
async function startStudentCourse(id){state.pendingCourseId=id;state.current=await api(`/api/projects/${id}`);state.studentProfile=loadStudentProfile()||{name:'Aluno de Teste FortixSeg',document:'',email:'aluno.teste@fortixseg.com.br',company:'FortixSeg',role:'Preview'};await studentMode(id)}
function studentProfileView(){const p=state.studentProfile||loadStudentProfile()||{};setHeader('Identificação do aluno','Esses dados serão usados no registro de conclusão e no certificado.');return `<div class="content learner-profile-wrap"><div class="card learner-profile-card"><div class="card-head"><b>Dados do aluno</b></div><div class="card-body"><div class="field"><label>Nome completo *</label><input id="spName" value="${esc(p.name||'')}" autocomplete="name"></div><div class="form-row mt"><div class="field"><label>CPF / documento</label><input id="spDocument" value="${esc(p.document||'')}"></div><div class="field"><label>E-mail</label><input id="spEmail" type="email" value="${esc(p.email||'')}" autocomplete="email"></div></div><div class="form-row mt"><div class="field"><label>Empresa</label><input id="spCompany" value="${esc(p.company||'')}"></div><div class="field"><label>Função</label><input id="spRole" value="${esc(p.role||'')}"></div></div><div class="notice info mt">O nome é obrigatório. Documento e e-mail ajudam a diferenciar alunos no mesmo computador.</div><div class="toolbar"><button class="btn outline" onclick="setRoute('student')">Cancelar</button><button class="btn primary" onclick="saveStudentProfileForm()">Salvar e continuar →</button></div></div></div></div>`}
async function saveStudentProfileForm(){const profile={name:$('#spName')?.value.trim()||'',document:$('#spDocument')?.value.trim()||'',email:$('#spEmail')?.value.trim()||'',company:$('#spCompany')?.value.trim()||'',role:$('#spRole')?.value.trim()||''};if(profile.name.length<3){toast('Informe o nome completo do aluno.');return}saveStudentProfileData(profile);const pending=state.pendingCourseId,ret=state.profileReturnRoute;state.pendingCourseId=null;state.profileReturnRoute=null;if(pending){await studentMode(pending);return}if(ret==='materials'&&state.current){state.route='materials';render();return}setRoute('student')}
function editStudentProfile(){state.studentProfile=loadStudentProfile();state.profileReturnRoute=state.route;state.pendingCourseId=null;state.route='student-profile';render()}
async function studentMode(id){state.pendingCourseId=null;state.current=await api(`/api/projects/${id}`);state.studentProfile=loadStudentProfile()||state.studentProfile||{name:'Aluno de Teste FortixSeg',document:'',email:'aluno.teste@fortixseg.com.br',company:'FortixSeg',role:'Preview'};state.route='student-course';const mods=state.current.payload.modules,first=mods[0],saved=loadStudentProgress();state.answers=saved?.assessmentAnswers||{};state.inlineAnswers=saved?.inlineAnswers||{};state.viewedSteps=saved?.viewedSteps&&typeof saved.viewedSteps==='object'?saved.viewedSteps:{};state.activeStudentStepKey=null;state.studentStepStartedAt=0;state.completedModules=Array.isArray(saved?.completedModules)?saved.completedModules.filter(id=>mods.some(m=>m.id===id)):[];state.assessmentAttempts=Number(saved?.assessmentAttempts)||0;state.assessmentPassed=!!saved?.assessmentPassed;state.lastScore=saved?.lastScore??null;state.certificateInfo=saved?.certificateInfo||null;if(saved&&mods.some(m=>m.id===saved.moduleId)){state.studentModule=saved.moduleId;const m=mods.find(x=>x.id===saved.moduleId),slides=moduleDeck(m,{source:false,mode:'student'});state.studentSlide=Math.max(0,Math.min(Number(saved.slide)||0,slides.length-1));toast('Progresso anterior recuperado.')}else{state.studentModule=first?.id;state.studentSlide=0}render()}
function studentSlideLabel(s,m){if(s.kind==='module-intro')return 'Abertura do módulo';if(s.kind==='source-page')return 'Conteúdo do módulo';if(s.kind==='module-quiz')return `Quiz · pergunta ${s.quizIndex+1} de ${s.quizTotal}`;if(s.kind==='module-end')return 'Fechamento do módulo';return 'Conteúdo do módulo'}
function studentCourse(){const p=state.current.payload,mods=p.modules,m=mods.find(x=>x.id===state.studentModule)||mods[0];if(!m)return '';state.studentModule=m.id;const slides=moduleDeck(m,{source:false,mode:'student'});state.studentSlide=Math.max(0,Math.min(state.studentSlide,slides.length-1));ensureStudentStepTimer();const s=slides[state.studentSlide],mi=mods.indexOf(m),pct=studentProgress(mods,m,state.studentSlide),modulePct=Math.round(((state.studentSlide+1)/slides.length)*100),remaining=studentStepRemainingMs(),canNext=remaining<=0,lastSlide=state.studentSlide===slides.length-1,lastCourse=mi===mods.length-1&&lastSlide,nextLabel=lastCourse?'Materiais e avaliação →':lastSlide?'Próximo módulo →':state.studentSlide===0?'Começar módulo →':'Continuar →',done=completedSet(),unlocked=unlockedModuleIndex(mods),detail=s.kind==='source-page'?`Página ${s.pageData?.page||''} de ${p.source?.pages||'?'}`:studentSlideLabel(s,m);setHeader(p.title,'Treinamento');return `<div class="content student-content immersive-course v15-course"><header class="student-player-header"><div class="student-player-actions"><button class="btn outline compact" onclick="setRoute('student')">← Sair</button><button class="btn outline compact modules-toggle" onclick="toggleStudentModules()" title="Mostrar ou ocultar módulos">☰ <span>Módulos</span></button></div><div class="student-player-title"><span>MÓDULO ${mi+1} DE ${mods.length} · ${esc(detail)}</span><h2>${esc(m.learningTitle||m.title)}</h2><div class="student-top-step">${moduleDots(slides,state.studentSlide,'studentSetSlide')}</div></div><div class="student-course-progress-compact"><div><span>Curso</span><b>${pct}%</b></div><div class="progress"><span style="width:${pct}%"></span></div><small>Módulo ${modulePct}%</small></div></header><div class="student-shell-v15 ${state.studentModulesCollapsed?'modules-collapsed':''}"><aside class="card student-nav student-nav-v15"><div class="student-progress-head"><b>Módulos</b><span>${mi+1}/${mods.length}</span></div><div class="module-list">${mods.map((x,i)=>{const complete=done.has(x.id),locked=i>unlocked&&!complete;return `<button class="module-item ${x.id===m.id?'active':''} ${locked?'locked-module':''}" ${locked?'disabled':''} onclick="studentSelectModule('${x.id}')" style="text-align:left"><b>${i+1}. ${esc(x.learningTitle||x.title)}</b><small>${complete?'Concluído':x.id===m.id?'Em andamento':locked?'Bloqueado':'A seguir'}</small></button>`}).join('')}</div></aside><main class="student-deck-main v15">${moduleDeckCard(m,slides,state.studentSlide,{mode:'student'})}<div class="deck-footer learner-fixed-controls v15-controls"><button class="btn outline" ${mi===0&&state.studentSlide===0?'disabled':''} onclick="studentMove(-1)">← Voltar</button><div id="studentAdvanceNote" class="student-control-center">${canNext?'<span class="step-ready">✓ Você já pode continuar</span>':`<span class="step-wait">Leia/observe esta etapa por mais <b>${Math.max(1,Math.ceil(remaining/1000))}s</b></span>`}</div><button id="studentNextBtn" data-ready-label="${esc(nextLabel)}" class="btn primary ${!canNext?'locked':''}" ${!canNext?'disabled':''} onclick="studentMove(1)">${canNext?nextLabel:`Aguarde ${Math.max(1,Math.ceil(remaining/1000))}s`}</button></div></main></div></div>`}
function materialsView(){state.route='materials';saveStudentProgress();render()}
function materialsScreen(){const p=state.current?.payload||{},items=p.materials||[],profile=state.studentProfile||loadStudentProfile()||{};setHeader('Materiais complementares',p.title||'Treinamento');return `<div class="content immersive-materials"><div class="materials-finish-shell"><div class="materials-finish-head"><span class="badge published">Conteúdo concluído</span><h2>Materiais complementares</h2><p>Antes da avaliação final, baixe os arquivos de apoio disponibilizados para este treinamento.</p></div><div class="card"><div class="card-head"><b>Arquivos disponíveis</b><span>${items.length}</span></div><div class="card-body material-student-list">${items.length?items.map(x=>`<a class="material-student-item" href="/api/projects/${state.current.id}/materials/${x.id}"><span class="material-icon">⇩</span><div><b>${esc(x.title||x.filename)}</b><small>${esc(x.filename)} · ${fmtBytes(x.size||0)}</small></div><strong>Baixar</strong></a>`).join(''):'<div class="empty">Este treinamento não possui materiais complementares adicionais.</div>'}</div></div><div class="card learner-summary-card"><div><small>ALUNO</small><b>${esc(profile.name||'')}</b><span>${esc([profile.company,profile.role].filter(Boolean).join(' · '))}</span></div><button class="btn outline" onclick="editStudentProfile()">Editar dados</button></div><div class="toolbar materials-actions"><button class="btn outline" onclick="state.route='student-course';render()">← Voltar ao treinamento</button><button class="btn primary" onclick="assessmentView()">Ir para avaliação final →</button></div></div></div>`}
async function issueCertificate(score){if(!state.current?.payload?.certificate)return null;try{const result=await api(`/api/projects/${state.current.id}/certificates/issue`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({student:state.studentProfile||loadStudentProfile()||{},answers:state.answers,completedAt:new Date().toISOString()})});state.certificateInfo=result;saveStudentProgress();return result}catch(e){toast('Não foi possível emitir o certificado: '+e.message);return null}}
function assessmentView(){state.route='assessment';state.assessmentIndex=0;saveStudentProgress();render()}
function assessment(){const p=state.current.payload,qs=p.questions,maxAttempts=Math.max(1,Number(p.attempts)||1);if(!qs.length){setHeader('Avaliação final',p.title);return `<div class="content assessment"><div class="card"><div class="empty">Este treinamento não possui avaliação final configurada.</div></div></div>`}if(!state.assessmentPassed&&state.assessmentAttempts>=maxAttempts){setHeader('Avaliação final',p.title);return `<div class="content assessment"><div class="card success-panel"><h2>Tentativas encerradas</h2><p class="muted">Você utilizou ${state.assessmentAttempts} de ${maxAttempts} tentativa(s). Último resultado: ${state.lastScore??0}%.</p><button class="btn outline" onclick="setRoute('student')">Voltar aos treinamentos</button></div></div>`}state.assessmentIndex=Math.max(0,Math.min(state.assessmentIndex,qs.length-1));const qi=state.assessmentIndex,q=qs[qi],pct=Math.round(((qi+1)/qs.length)*100);setHeader('Avaliação final',p.title);return `<div class="content assessment single-question immersive-assessment"><div class="assessment-shell"><div class="assessment-progress"><div><b>Questão ${qi+1} de ${qs.length}</b><span>Nota mínima ${p.passingScore}% · tentativa ${Math.min(maxAttempts,state.assessmentAttempts+1)} de ${maxAttempts}</span></div><div class="progress"><span style="width:${pct}%"></span></div></div><div class="card question-card"><div class="card-body"><span class="badge type">AVALIAÇÃO</span><h2>${esc(q.question)}</h2><div class="assessment-options">${q.options.map((o,i)=>`<label class="option ${state.answers[q.id]===i?'selected':''}"><input type="radio" name="q_${q.id}" value="${i}" ${state.answers[q.id]===i?'checked':''} onchange="answer('${q.id}',${i});render()"><span><b>${String.fromCharCode(65+i)}</b>${esc(o)}</span></label>`).join('')}</div></div></div><div class="deck-footer"><button class="btn outline" ${qi===0?'disabled':''} onclick="assessmentMove(-1)">← Anterior</button><div class="assessment-dots">${qs.map((_,i)=>`<button class="${i===qi?'active':''} ${state.answers[qs[i].id]!==undefined?'answered':''}" onclick="assessmentGo(${i})"></button>`).join('')}</div>${qi<qs.length-1?`<button class="btn primary" onclick="assessmentMove(1)">Próxima questão →</button>`:`<button class="btn success" onclick="finishAssessment()">Finalizar avaliação ✓</button>`}</div></div></div>`}
function assessmentMove(delta){state.assessmentIndex=Math.max(0,Math.min(state.current.payload.questions.length-1,state.assessmentIndex+delta));saveStudentProgress();render()}
function assessmentGo(i){state.assessmentIndex=i;render()}
function answer(id,i){state.answers[id]=i;saveStudentProgress()}
function retryAssessment(){state.answers={};state.assessmentIndex=0;saveStudentProgress();closeModal();render()}
function restartCourse(){clearStudentProgress();state.completedModules=[];state.inlineAnswers={};state.viewedSteps={};state.activeStudentStepKey=null;state.studentStepStartedAt=0;state.answers={};state.assessmentAttempts=0;state.assessmentPassed=false;state.lastScore=null;state.certificateInfo=null;closeModal();studentMode(state.current.id)}
async function finishAssessment(){const p=state.current.payload,qs=p.questions;if(!qs.length){toast('Não há questões configuradas.');return}const missing=qs.findIndex(q=>state.answers[q.id]===undefined);if(missing>=0){state.assessmentIndex=missing;toast('Responda todas as questões antes de finalizar.');render();return}let hit=0;qs.forEach(q=>{if(state.answers[q.id]===q.correctIndex)hit++});const score=Math.round(hit/qs.length*100),pass=score>=p.passingScore,maxAttempts=Math.max(1,Number(p.attempts)||1);state.assessmentAttempts+=1;state.assessmentPassed=pass;state.lastScore=score;let cert=null;if(pass&&p.certificate)cert=await issueCertificate(score);saveStudentProgress();const remaining=maxAttempts-state.assessmentAttempts;modal(`<div class="success-panel"><div class="score-ring" style="--score:${score*3.6}deg;position:relative"><strong>${score}%</strong></div><h2>${pass?'Aprovado!':'Resultado abaixo da nota mínima'}</h2><p class="muted">Você acertou ${hit} de ${qs.length} questões. Nota mínima: ${p.passingScore}%.</p>${pass&&p.certificate?(cert?`<div class="notice good"><b>Certificado emitido.</b><br>Código ${esc(cert.code)}</div>`:'<div class="notice warn">Aprovado, mas a emissão do certificado precisa ser tentada novamente.</div>'):''}${!pass&&remaining>0?`<div class="notice warn">Você ainda possui ${remaining} tentativa(s).</div>`:''}<div class="toolbar"><button class="btn outline" onclick="closeModal();setRoute('student')">Voltar aos treinamentos</button>${cert?`<a class="btn success" href="${esc(cert.downloadUrl)}">⇩ Baixar certificado</a>`:''}${!pass&&remaining>0?'<button class="btn primary" onclick="retryAssessment()">Tentar novamente</button>':pass?'<button class="btn primary" onclick="restartCourse()">Refazer treinamento</button>':''}</div></div>`,'Resultado')}
async function openProject(id,step=3){state.current=await api(`/api/projects/${id}`);state.step=step;state.selectedModule=null;state.route='new';render()}
async function deleteProject(id){if(!confirm('Excluir este treinamento e seus dados locais?'))return;await api(`/api/projects/${id}`,{method:'DELETE'});await loadProjects();if(state.current?.id===id)state.current=null;render();toast('Treinamento excluído.')}
function goStep(n){state.step=n;state.route='new';render()}
function showSource(pages){const src=state.current.payload.sourcePages.filter(x=>pages.includes(x.page));modal(src.map(x=>`<h4>Página ${x.page} <small class="muted">${esc(x.role||'CONTENT')}${x.title?' · '+esc(x.title):''}</small></h4><div class="source-text">${esc(x.text||'Sem texto extraído nesta página.')}</div>`).join('')||'<div class="empty">Sem páginas de origem associadas.</div>','Fonte no PDF')}
function modal(body,title=''){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><b>${esc(title)}</b><button class="icon-btn" onclick="closeModal()">×</button></div><div class="modal-body">${body}</div></div></div>`}
function closeModal(){$('#modalRoot').innerHTML=''}

function learnerKeyboardNavigation(event){
  if(state.route!=='student-course'&&state.route!=='assessment')return;
  if(document.querySelector('.modal-backdrop'))return;
  const tag=(event.target?.tagName||'').toLowerCase();
  if(['input','textarea','select','button'].includes(tag)||event.target?.isContentEditable)return;
  if(event.key==='ArrowRight'||event.key==='PageDown'||event.key===' '){
    event.preventDefault();
    if(state.route==='student-course')studentMove(1);else if(state.assessmentIndex<state.current.payload.questions.length-1)assessmentMove(1);
  }else if(event.key==='ArrowLeft'||event.key==='PageUp'){
    event.preventDefault();
    if(state.route==='student-course')studentMove(-1);else assessmentMove(-1);
  }
}
document.addEventListener('keydown',learnerKeyboardNavigation);
function render(){document.body.classList.toggle('student-immersive',['student-course','assessment','materials','student-profile'].includes(state.route));let html='';if(state.route==='dashboard')html=dashboard();else if(state.route==='library')html=library();else if(state.route==='student')html=studentList();else if(state.route==='student-profile')html=studentProfileView();else if(state.route==='student-course')html=studentCourse();else if(state.route==='materials')html=materialsScreen();else if(state.route==='assessment')html=assessment();else if(state.route==='new'){if(!state.current||state.step===1)html=uploadView();else if(state.step===2)html=analysisView();else if(state.step===3)html=structureView();else if(state.step===4)html=previewView();else if(state.step===5)html=reviewView();else html=publishView()}$('#view').innerHTML=html;if(state.route==='new'&&(!state.current||state.step===1))bindUpload();if(state.route==='student-course')refreshStudentAdvanceTimer();else if(studentAdvanceTimer){clearInterval(studentAdvanceTimer);studentAdvanceTimer=null}hydratePdfCanvases()}
$$('.nav').forEach(n=>n.onclick=()=>setRoute(n.dataset.route));$('#refreshBtn').onclick=async()=>{await loadProjects();render();toast('Dados atualizados.')};
(async()=>{try{await loadProjects();render()}catch(e){$('#view').innerHTML=`<div class="content"><div class="notice bad">Falha ao acessar o servidor: ${esc(e.message)}</div></div>`}})();
